let breeze = wind * (0.32 * t + 0.22 * sin(t * 0.8 + p.y * 1.5));
let q = vec2<f32>(p.x - breeze, p.y + t * fall_speed * 0.65) * density;
let id = floor(q);
let seed = hash(id);
let local = fract(q) - vec2<f32>(0.5) - (vec2<f32>(seed, hash(id + vec2<f32>(4.3, 8.1))) - vec2<f32>(0.5)) * 0.28;
let angle = seed * 6.283 + t * (0.45 + seed * 0.7) + wind * sin(t + seed * 8.0);
let a = vec2<f32>(local.x * cos(angle) - local.y * sin(angle), local.x * sin(angle) + local.y * cos(angle)) / (leaf_size * 0.38);
let shape = abs(a.x) / 0.65 + a.y * a.y;
let leaf = 1.0 - smoothstep(0.9, 1.04, shape);
let vein = (1.0 - smoothstep(0.025, 0.065, abs(a.x))) * (1.0 - smoothstep(0.78, 1.0, abs(a.y)));
let branches = (1.0 - smoothstep(0.025, 0.065, abs(fract(a.y * 3.2 - abs(a.x) * 2.0) - 0.5))) * 0.22;
let warm = mix(c1, c2, smoothstep(0.15, 0.85, seed));
let face = mix(warm, c3, 0.24 * smoothstep(-0.5, 0.5, a.x));
let front = mix(face, c5, clamp(vein * 0.65 + branches, 0.0, 0.75));

let r = vec2<f32>(p.x - breeze * 0.42 + 3.7, p.y + t * fall_speed * 0.28) * density * 1.5;
let rid = floor(r);
let rs = hash(rid + vec2<f32>(17.2, 9.1));
let rl = fract(r) - vec2<f32>(0.5);
let ra = rs * 6.283 - t * 0.38;
let b = vec2<f32>(rl.x * cos(ra) - rl.y * sin(ra), rl.x * sin(ra) + rl.y * cos(ra)) / (leaf_size * 0.29);
let distant = 1.0 - smoothstep(0.88, 1.08, abs(b.x) / 0.6 + b.y * b.y);
let haze = cloud(p * 0.65 + vec2<f32>(-t * 0.035, t * 0.025));
let base = mix(c4, c3, haze * 0.4) * vec3<f32>(0.62);
let back = mix(base, mix(c3, c2, rs) * vec3<f32>(0.75), distant * 0.85);
let color = mix(back, front, leaf);
return mix(bg, clamp(color, vec3<f32>(0.0), vec3<f32>(1.0)), strength);

let time = t * motion;
let warp = vec2<f32>(
    sin(p.y * 2.8 + time * 0.9) + 0.4 * cos(p.x * 3.5 - time),
    cos(p.x * 2.4 - time * 0.8) + 0.4 * sin(p.y * 3.8 + time)
);
let q = (p + warp * (bend * 0.28)) * shape_density;
let angle = 0.35 * sin(time * 0.45);
let r = vec2<f32>(
    q.x * cos(angle) - q.y * sin(angle),
    q.x * sin(angle) + q.y * cos(angle)
);
let drift = r + vec2<f32>(time * 0.15, time * 0.23);
let cell = floor(drift);
let local = fract(drift) - vec2<f32>(0.5);
let seed = hash(cell);
let spin = time * (0.35 + seed * 0.45) + seed * 6.28318;
let v = vec2<f32>(
    local.x * cos(spin) - local.y * sin(spin),
    local.x * sin(spin) + local.y * cos(spin)
);
let square = max(abs(v.x), abs(v.y));
let diamond = (abs(v.x) + abs(v.y)) * 0.72;
let circle = length(v);
let metric = mix(mix(square, diamond, smoothstep(0.15, 0.65, seed)), circle, smoothstep(0.65, 0.95, seed));
let radius = 0.29 + 0.055 * sin(time * 1.7 + seed * 9.0);
let edge = abs(metric - radius);
let outline = 1.0 - smoothstep(0.018, 0.055, edge);
let halo = exp(-edge * 15.0) * glow;
let fill = 1.0 - smoothstep(radius - 0.025, radius, metric);
let hue = 0.5 + 0.5 * sin(r.x * 1.3 + r.y * 1.7 + time * 0.65 + seed * 3.0);
let hot = mix(c1, c2, smoothstep(0.05, 0.8, hue));
let cool = mix(c5, c3, smoothstep(0.1, 0.9, hue));
let ink = mix(hot, cool, 0.5 + 0.5 * sin(seed * 14.0 + time * 0.4));
let field = 0.5 + 0.5 * sin(q.x * 2.7 - q.y * 2.1 + time + bend * sin(q.y * 3.0));
let base = mix(c5, c1, field) * 0.38;
let body = mix(base, ink * 0.72, fill * 0.85);
let rim = mix(ink, c4, 0.35 + 0.3 * sin(seed * 12.0 + time));
let color = clamp(body + rim * (outline * 0.65 + halo * 0.35), vec3<f32>(0.0), vec3<f32>(1.0));
return mix(bg, color, strength);

let density = 1.3 + amount * 0.32;
let drift = t * gravity * 0.24;
let wave = sin(p.y * 2.3 + t * 0.35) * 0.18 + sin(p.x * 1.7 - t * 0.22) * 0.12;
let flow = p + vec2<f32>(wave, drift);
let grid = flow * vec2<f32>(density);
let row = floor(grid.y);
let staggered = grid + vec2<f32>(sin(row * 2.4) * 0.28, 0.0);
let cell = floor(staggered);
let q = fract(staggered) - vec2<f32>(0.5);
let seed = hash(cell);
let angle = sin(t * 0.32 + seed * 6.283 + row * 0.45) * 0.65 + seed * 6.283;
let r = vec2<f32>(q.x * cos(angle) - q.y * sin(angle), q.x * sin(angle) + q.y * cos(angle));
let size = shape_size * (0.68 + seed * 0.18);
let d = max(abs(r.x) * 0.866025 + r.y * 0.5, -r.y) - size * 0.65;
let fill = 1.0 - smoothstep(-0.014, 0.012, d);
let rim = exp(-abs(d) * 85.0);
let halo = exp(-max(d, 0.0) * 17.0) * (1.0 - fill);
let bands = 0.5 + 0.5 * sin(d * 110.0 - t * 1.8 + seed * 8.0);
let interior = mix(0.32, 0.92, bands) * fill;
let contour = pow(0.5 + 0.5 * sin(d * 62.0 - t * 1.1), 14.0) * exp(-max(d, 0.0) * 7.0) * (1.0 - fill);
let tide = 0.5 + 0.5 * sin(p.x * 1.9 + p.y * 2.6 + sin(p.y * 3.0 - t * 0.4) + t * 0.23);
let blue = mix(vec3<f32>(0.025, 0.17, 0.85), vec3<f32>(0.02, 0.78, 1.0), seed);
let neon = mix(blue, vec3<f32>(0.39, 0.16, 1.0), smoothstep(0.7, 1.0, seed) * 0.65);
let base = mix(vec3<f32>(0.015, 0.045, 0.19), vec3<f32>(0.035, 0.19, 0.43), tide);
let activity = smoothstep(0.0, 0.7, amount);
let light = interior * 0.85 + rim * 0.8 + halo * glow * 0.4 + contour * glow * 0.18;
let color = clamp(base + neon * vec3<f32>(activity * light), vec3<f32>(0.0), vec3<f32>(1.0));
return mix(bg, color, strength);

let density = 1.2 + amount * 0.28;
let warp = vec2<f32>(sin(p.y * 3.0 + t * 0.7), cos(p.x * 2.6 - t * 0.6)) * vec2<f32>(0.16);
let pos = (p + warp) * vec2<f32>(density);
let column = floor(pos.x);
let seed = hash(vec2<f32>(column, 7.3));
let fall = t * gravity * (0.4 + seed * 0.55);
let grid = pos + vec2<f32>(0.0, fall + seed * 8.0);
let cell = floor(grid);
let id = hash(cell);
let q = fract(grid) - vec2<f32>(0.5);
let angle = t * (seed - 0.5) * 3.0 + id * 6.283;
let r = vec2<f32>(q.x * cos(angle) - q.y * sin(angle), q.x * sin(angle) + q.y * cos(angle));
let size = shape_size * (0.55 + id * 0.25);
let circle = length(r) - size;
let square = max(abs(r.x), abs(r.y)) - size * 0.85;
let diamond = (abs(r.x) + abs(r.y)) * 0.7071 - size * 0.8;
let triangle = max(abs(r.x) * 0.866 + r.y * 0.5, -r.y) - size * 0.55;
let d = select(select(circle, square, id > 0.25), select(diamond, triangle, id > 0.75), id > 0.5);
let fill = 1.0 - smoothstep(-0.012, 0.015, d);
let outline = exp(-abs(d) * 70.0);
let hollow = step(0.48, fract(id * 7.9));
let graphic = mix(fill, outline, hollow);
let halo = exp(-max(d, 0.0) * 15.0) * (1.0 - fill);
let stripe = smoothstep(0.4, 0.6, sin((r.x + r.y) * 65.0 + t * 2.0));
let hatch = fill * stripe * hollow * 0.32;
let trail = exp(-abs(q.x) * 60.0) * smoothstep(0.0, 0.48, q.y) * 0.17;
let source = mix(mix(c1, c2, seed), c3, id);
let activity = smoothstep(0.0, 0.6, amount);
let paper = 0.14 + 0.06 * noise(p * vec2<f32>(3.0) + vec2<f32>(t * 0.08));
let light = paper + activity * (0.8 * graphic + hatch + glow * (halo * 0.19 + trail));
let color = clamp(source * vec3<f32>(light), vec3<f32>(0.0), vec3<f32>(1.0));
return mix(bg, color, strength);

let density = 1.6 + amount * 0.48;
let drift = vec2<f32>(sin(t * 0.43), t * gravity * 0.38);
let warp = p + vec2<f32>(sin(p.y * 3.0 + t * gravity), cos(p.x * 2.5 - t)) * vec2<f32>(0.16);
let grid = warp * vec2<f32>(density) + drift;
let cell = floor(grid);
let seed = hash(cell);
let q = fract(grid) - vec2<f32>(0.5);
let angle = t * gravity * (seed - 0.5) + seed * 6.2832;
let r = vec2<f32>(q.x * cos(angle) - q.y * sin(angle), q.x * sin(angle) + q.y * cos(angle));
let size = shape_size * (0.65 + 0.25 * sin(t * 2.0 + seed * 12.0));
let box = max(abs(r.x), abs(r.y)) - size;
let disk = length(r) - size;
let diamond = (abs(r.x) + abs(r.y)) * 0.7071 - size;
let d = select(select(box, disk, seed > 0.33), diamond, seed > 0.67);
let fill = 1.0 - smoothstep(-0.015, 0.015, d);
let ring = 1.0 - smoothstep(0.014, 0.033, abs(d));
let stripe = step(0.5, fract((r.x + r.y) * 9.0 + t * gravity));
let checker = step(0.5, fract((cell.x + cell.y) * 0.5));
let ink = mix(fill, max(ring, fill * stripe), step(0.45, seed));
let graphic = mix(ink, 1.0 - ink, checker);
let accent = select(mix(c1, c2, step(0.5, seed)), c3, seed > 0.8);
let accentMask = step(0.78, hash(cell + vec2<f32>(19.2, 4.6)));
let paper = mix(accent * vec3<f32>(0.025), mix(accent, vec3<f32>(1.0), 0.75), graphic);
let colored = mix(accent * vec3<f32>(0.12), accent, graphic);
let halo = exp(-abs(d) * 26.0) * glow * 0.22;
let color = clamp(mix(paper, colored, accentMask) + accent * vec3<f32>(halo * accentMask), vec3<f32>(0.0), vec3<f32>(1.0));
return mix(bg, color, strength);

let power = clamp(amount / 10.0, 0.0, 1.0);
let uv = p * vec2<f32>(2.0) + vec2<f32>(t * 0.035, -t * 0.025);
let cell = floor(uv);
let seed = hash(cell);
let local = (fract(uv) - vec2<f32>(0.5)) * vec2<f32>(2.0);
let angle = t * 0.16 * select(-1.0, 1.0, seed > 0.5) + seed * 6.28318;
let q = vec2<f32>(local.x * cos(angle) - local.y * sin(angle), local.x * sin(angle) + local.y * cos(angle));
let bounce = 0.93 + 0.07 * sin(t * 1.4 + seed * 12.0);
let v = q / vec2<f32>(bounce);
let a = abs(v);
let hex = max(a.y, a.x * 0.866025 + a.y * 0.5) - 0.59;
let outline = 1.0 - smoothstep(0.007, 0.023, abs(hex));
let halo = exp(-abs(hex) * 24.0);
let inside = 1.0 - smoothstep(-0.015, 0.005, hex);
let spokes = min(abs(v.y), min(abs(v.y * 0.5 + v.x * 0.866025), abs(v.y * 0.5 - v.x * 0.866025)));
let ribs = (1.0 - smoothstep(0.005, 0.016, spokes)) * inside;
let radius = length(v);
let hub = 1.0 - smoothstep(0.04, 0.055, radius);
let hubRing = 1.0 - smoothstep(0.006, 0.018, abs(radius - 0.095));
let sector = floor((atan2(v.y, v.x) + 3.141593) / 1.047198);
let hue = fract(seed * 0.8 + sector / 6.0 + t * 0.015);
let candy = mix(hsv(hue, 0.82, 1.0), clamp(c1, vec3<f32>(0.0), vec3<f32>(1.0)), 0.12);
let rim = hsv(fract(seed + t * 0.025), 0.63, 1.0);
let facet = inside * (0.025 + 0.025 * fract(sector * 0.37 + seed));
let brightness = 0.55 + power * 0.35;
let lines = rim * vec3<f32>((outline * 0.66 + halo * 0.065 + hubRing * 0.32) * brightness);
let panels = candy * vec3<f32>(facet + ribs * 0.28 * brightness);
let center = mix(c2, vec3<f32>(0.7, 0.9, 1.0), 0.6) * vec3<f32>(hub * 0.42);
let grid = abs(fract(uv) - vec2<f32>(0.5));
let peg = exp(-dot(grid, grid) * 800.0);
let base = vec3<f32>(0.006, 0.009, 0.02) + c3 * vec3<f32>(0.012 + peg * 0.06);
let vignette = 1.0 / (1.0 + dot(p, p) * 0.1);
return clamp((base + lines + panels + center) * vec3<f32>(vignette), vec3<f32>(0.0), vec3<f32>(0.8));

let wind = sin(t * 0.7 + p.y * 1.8) * 0.18;
let sky = cloud(p * vec2<f32>(1.4, 2.8) + vec2<f32>(t * 0.12, 0.0));
let haze = mix(c1 * vec3<f32>(0.48), c3 * vec3<f32>(0.85), smoothstep(0.15, 0.85, sky));
let spacing = 1.15 - amount * 0.065;
let drift = vec2<f32>(p.x + wind - t * 0.22, p.y + t * gravity * 0.32);
let grid = drift / vec2<f32>(spacing);
let cell = floor(grid);
let seed = hash(cell);
let local = (fract(grid) - vec2<f32>(0.5)) * vec2<f32>(spacing);
let angle = seed * 6.2831853 + sin(t * 1.8 + seed * 12.0) * 0.9;
let q = vec2<f32>(local.x * cos(angle) - local.y * sin(angle), local.x * sin(angle) + local.y * cos(angle)) / vec2<f32>(shape_size * (0.65 + seed * 0.45));
let taper = max(0.0, 1.0 - q.y * q.y);
let edge = abs(q.x) - taper * (0.42 + 0.09 * cos(q.y * 19.0));
let leaf = (1.0 - smoothstep(-0.025, 0.025, edge)) * (1.0 - smoothstep(0.92, 1.02, abs(q.y)));
let vein = exp(-abs(q.x) * 65.0) * leaf;
let leafColor = mix(mix(c1, c3, smoothstep(0.1, 0.7, seed)), c2, step(0.84, seed));
let litLeaf = leafColor * vec3<f32>(0.78 + 0.22 * sin(q.y * 3.0 + seed * 5.0)) + c3 * vec3<f32>(vein * 0.3);
let rainCoord = p.x * 28.0 + p.y * 5.0;
let rain = pow(0.5 + 0.5 * cos(rainCoord), 28.0) * pow(0.5 + 0.5 * sin(p.y * 20.0 + t * gravity * 9.0 + floor(rainCoord) * 2.7), 12.0);
let halo = exp(-max(edge, 0.0) * 12.0) * exp(-max(abs(q.y) - 0.9, 0.0) * 12.0);
let color = mix(haze, litLeaf, leaf) + c3 * vec3<f32>(rain * 0.22 + glow * halo * 0.22);
return mix(bg, clamp(color, vec3<f32>(0.0), vec3<f32>(1.0)), strength);

let scale = 1.2 + amount * 0.32;
let clock = t * (0.5 + gravity * 0.85);
let pos = p * vec2<f32>(scale) + vec2<f32>(0.0, clock * 0.16);
let row = floor(pos.y);
let seed = hash(vec2<f32>(row, 7.3));
let direction = select(-1.0, 1.0, fract(row * 0.5) > 0.25);
let dash = clock * (0.6 + seed) + 1.3 * smoothstep(-0.7, 0.7, sin(clock * 1.7 + seed * 12.0));
let x = pos.x + direction * dash + seed * 8.0;
let y = fract(pos.y) - 0.5;
let pair = floor(x * 0.5);
let u = fract(x * 0.5) * 2.0;
let slope = select(-0.76, 0.76, fract(row * 0.5) > 0.25);
let split = 1.0 + slope * y;
let side = step(split, u);
let center = mix(split * 0.5, 1.0 + split * 0.5, side);
let halfwidth = mix(split * 0.5, 1.0 - split * 0.5, side);
let inset = 0.11 - shape_size * 0.13;
let edge = min((halfwidth - abs(u - center)) * 0.93, 0.5 - abs(y)) - inset;
let body = smoothstep(-0.018, 0.018, edge);
let bevel = 1.0 - smoothstep(0.018, 0.085, edge);
let id = hash(vec2<f32>(pair * 2.0 + side, row));
let paint = mix(c1, c2, 0.15 + 0.75 * id);
let shading = 0.72 + 0.28 * (y + 0.5) + 0.12 * sin(id * 18.0 + clock * 2.0);
let face = paint * vec3<f32>(shading);
let rim = mix(c2, c3, 0.3) * vec3<f32>(bevel * 0.35);
let halo = exp(-max(-edge, 0.0) * 18.0) * (1.0 - body) * glow;
let ground = c1 * vec3<f32>(0.23) + c2 * vec3<f32>(0.07);
let color = mix(ground, face + rim, body) + c1 * vec3<f32>(halo * 0.38);
return mix(bg, clamp(color, vec3<f32>(0.0), vec3<f32>(1.0)), strength);

let density = (0.8 + amount * 0.13) / (0.45 + shape_size * 2.0);
let y = p.y * density + t * gravity * 0.32;
let row = floor(y);
let clock = t * (0.65 + gravity * 1.3) + hash(vec2<f32>(row, 8.0)) * 7.0;
let beat = floor(clock);
let dart = smoothstep(0.12, 0.38, fract(clock));
let start = hash(vec2<f32>(row, beat)) * 4.0;
let finish = hash(vec2<f32>(row, beat + 1.0)) * 4.0;
let x = p.x * density * 0.72 + mix(start, finish, dart);
let cell = floor(x);
let uv = vec2<f32>(fract(x), fract(y));
let lean = 0.22 * cos(row * 2.3);
let divider = 0.5 + lean * (uv.y * 2.0 - 1.0);
let side = step(divider, uv.x);
let seam = abs(uv.x - divider) / sqrt(1.0 + 4.0 * lean * lean);
let edge = min(min(uv.x, 1.0 - uv.x), min(min(uv.y, 1.0 - uv.y), seam));
let tile = smoothstep(0.012, 0.028, edge);
let seed = hash(vec2<f32>(cell * 2.0 + side, row));
let base = mix(c1, c2, seed);
let tint = mix(base, c3, 0.26 * step(0.76, seed));
let shading = 0.72 + 0.25 * uv.y + 0.08 * sin(seed * 6.283 + t * 1.4);
let rim = exp(-edge * 65.0) * tile;
let halo = exp(-edge * 22.0) * glow * 0.12;
let grout = mix(bg, c1, 0.2);
let color = mix(grout, tint * vec3<f32>(shading), tile)
  + mix(c2, c3, 0.35) * vec3<f32>(rim * (0.18 + glow * 0.2) + halo);
return mix(bg, clamp(color, vec3<f32>(0.0), vec3<f32>(1.0)), strength);

let density = 0.7 + amount * 0.24;
let column = floor(p.x * density);
let seed = hash(vec2<f32>(column, 7.3));
let phase = fract(t * gravity * 0.16 + seed);
let fall = 4.0 * phase * phase;
let grid = vec2<f32>(p.x * density, p.y * density + fall + seed * 5.0);
let cell = floor(grid);
let q = fract(grid) - vec2<f32>(0.5);
let angle = t * (seed - 0.5) * 1.5 + seed * 6.283;
let r = vec2<f32>(q.x * cos(angle) - q.y * sin(angle), q.x * sin(angle) + q.y * cos(angle));
let size = shape_size * (0.42 + seed * 0.14);
let circle = length(r) - size;
let square = max(abs(r.x), abs(r.y)) - size * 0.85;
let diamond = (abs(r.x) + abs(r.y)) * 0.7071 - size * 0.85;
let triangle = max(abs(r.x) * 0.866 + r.y * 0.5, -r.y) - size * 0.55;
let kind = fract(seed * 13.7);
let d = select(select(circle, square, kind > 0.25), select(diamond, triangle, kind > 0.75), kind > 0.5);
let fill = 1.0 - smoothstep(-0.012, 0.018, d);
let edge = exp(-abs(d) * 65.0);
let halo = exp(-max(d, 0.0) * 13.0) * (1.0 - fill);
let hue = fract(seed + cell.y * 0.117 + t * 0.035);
let neon = mix(palette(hue), mix(c1, c2, seed), 0.25);
let streak = exp(-abs(q.x) * 55.0) * smoothstep(-0.12, 0.42, q.y) * (0.2 + phase * 0.8);
let base = mix(bg, c3 * vec3<f32>(0.22, 0.26, 0.38), 0.6) + mix(c1, c2, 0.5) * vec3<f32>(0.035);
let activity = smoothstep(0.0, 0.5, amount);
let color = clamp(base + activity * (neon * (fill * 0.78 + halo * glow * 0.48 + streak * glow * 0.24) + mix(neon, c2, 0.35) * edge * 0.45), vec3<f32>(0.0), vec3<f32>(1.0));
return mix(bg, color, strength);

let density = 0.8 + amount * 0.23;
let column = floor(p.x * density);
let seed = hash(vec2<f32>(column, 7.3));
let clock = t * gravity * 0.42 + seed * 8.0;
let fall = floor(clock) + pow(fract(clock), 2.0);
let grid = vec2<f32>(p.x * density, p.y * density + fall);
let cell = floor(grid);
let id = hash(cell + vec2<f32>(2.7, 9.1));
let q = fract(grid) - vec2<f32>(0.5);
let angle = sin(clock * 2.4 + id * 14.0) * 0.65 + id * 6.283;
let r = vec2<f32>(q.x * cos(angle) - q.y * sin(angle), q.x * sin(angle) + q.y * cos(angle));
let size = shape_size * (0.65 + 0.2 * sin(clock * 5.0 + id * 20.0));
let round = length(r) - size;
let box = max(abs(r.x), abs(r.y)) - size * 0.86;
let star = length(r) - size * (0.78 + 0.22 * cos(atan2(r.y, r.x) * 5.0));
let d = select(select(round, box, id > 0.33), star, id > 0.66);
let body = 1.0 - smoothstep(-0.006, 0.008, d);
let eye1 = 1.0 - smoothstep(0.018, 0.03, length(r - vec2<f32>(-0.065, 0.035)));
let eye2 = 1.0 - smoothstep(0.018, 0.03, length(r - vec2<f32>(0.065, 0.035)));
let grin = (1.0 - smoothstep(0.008, 0.018, abs(length(r - vec2<f32>(0.0, 0.025)) - 0.09))) * (1.0 - smoothstep(-0.025, -0.012, r.y));
let accent = select(select(c1, c2, id > 0.33), c3, id > 0.66);
let paper = mix((c1 + c2 + c3) / 3.0, vec3<f32>(1.0), 0.7);
let ink = mix(bg, accent, 0.08);
let dots = step(0.83, sin(p.x * 48.0) * sin(p.y * 48.0));
let backdrop = mix(ink, paper, 0.08 + dots * 0.12);
let halo = exp(-max(d, 0.0) * 16.0) * (1.0 - body) * glow * 0.22;
let face = mix(paper, ink, clamp(eye1 + eye2 + grin, 0.0, 1.0));
let activity = smoothstep(0.0, 0.8, amount);
let color = clamp(mix(backdrop + accent * halo, face, body * activity), vec3<f32>(0.0), vec3<f32>(1.0));
return mix(bg, color, strength);

let density = 1.6 + amount * 0.48;
let drift = vec2<f32>(sin(t * 0.43), t * gravity * 0.38);
let warp = p + vec2<f32>(sin(p.y * 3.0 + t * gravity), cos(p.x * 2.5 - t)) * vec2<f32>(0.16);
let grid = warp * vec2<f32>(density) + drift;
let cell = floor(grid);
let seed = hash(cell);
let q = fract(grid) - vec2<f32>(0.5);
let angle = t * gravity * (seed - 0.5) + seed * 6.2832;
let r = vec2<f32>(q.x * cos(angle) - q.y * sin(angle), q.x * sin(angle) + q.y * cos(angle));
let size = shape_size * (0.65 + 0.25 * sin(t * 2.0 + seed * 12.0));
let box = max(abs(r.x), abs(r.y)) - size;
let disk = length(r) - size;
let diamond = (abs(r.x) + abs(r.y)) * 0.7071 - size;
let d = select(select(box, disk, seed > 0.33), diamond, seed > 0.67);
let fill = 1.0 - smoothstep(-0.015, 0.015, d);
let ring = 1.0 - smoothstep(0.014, 0.033, abs(d));
let stripe = step(0.5, fract((r.x + r.y) * 9.0 + t * gravity));
let checker = step(0.5, fract((cell.x + cell.y) * 0.5));
let ink = mix(fill, max(ring, fill * stripe), step(0.45, seed));
let graphic = mix(ink, 1.0 - ink, checker);
let accent = select(mix(c1, c2, step(0.5, seed)), c3, seed > 0.8);
let accentMask = step(0.78, hash(cell + vec2<f32>(19.2, 4.6)));
let paper = mix(accent * vec3<f32>(0.025), mix(accent, vec3<f32>(1.0), 0.75), graphic);
let colored = mix(accent * vec3<f32>(0.12), accent, graphic);
let halo = exp(-abs(d) * 26.0) * glow * 0.22;
let color = clamp(mix(paper, colored, accentMask) + accent * vec3<f32>(halo * accentMask), vec3<f32>(0.0), vec3<f32>(1.0));
return mix(bg, color, strength);

let density = 1.2 + amount * 0.28;
let warp = vec2<f32>(sin(p.y * 3.0 + t * 0.7), cos(p.x * 2.6 - t * 0.6)) * vec2<f32>(0.16);
let pos = (p + warp) * vec2<f32>(density);
let column = floor(pos.x);
let seed = hash(vec2<f32>(column, 7.3));
let fall = t * gravity * (0.4 + seed * 0.55);
let grid = pos + vec2<f32>(0.0, fall + seed * 8.0);
let cell = floor(grid);
let id = hash(cell);
let q = fract(grid) - vec2<f32>(0.5);
let angle = t * (seed - 0.5) * 3.0 + id * 6.283;
let r = vec2<f32>(q.x * cos(angle) - q.y * sin(angle), q.x * sin(angle) + q.y * cos(angle));
let size = shape_size * (0.55 + id * 0.25);
let circle = length(r) - size;
let square = max(abs(r.x), abs(r.y)) - size * 0.85;
let diamond = (abs(r.x) + abs(r.y)) * 0.7071 - size * 0.8;
let triangle = max(abs(r.x) * 0.866 + r.y * 0.5, -r.y) - size * 0.55;
let d = select(select(circle, square, id > 0.25), select(diamond, triangle, id > 0.75), id > 0.5);
let fill = 1.0 - smoothstep(-0.012, 0.015, d);
let outline = exp(-abs(d) * 70.0);
let hollow = step(0.48, fract(id * 7.9));
let graphic = mix(fill, outline, hollow);
let halo = exp(-max(d, 0.0) * 15.0) * (1.0 - fill);
let stripe = smoothstep(0.4, 0.6, sin((r.x + r.y) * 65.0 + t * 2.0));
let hatch = fill * stripe * hollow * 0.32;
let trail = exp(-abs(q.x) * 60.0) * smoothstep(0.0, 0.48, q.y) * 0.17;
let source = mix(mix(c1, c2, seed), c3, id);
let activity = smoothstep(0.0, 0.6, amount);
let paper = 0.14 + 0.06 * noise(p * vec2<f32>(3.0) + vec2<f32>(t * 0.08));
let light = paper + activity * (0.8 * graphic + hatch + glow * (halo * 0.19 + trail));
let color = clamp(source * vec3<f32>(light), vec3<f32>(0.0), vec3<f32>(1.0));
return mix(bg, color, strength);

let spacing = 1.4 / (0.7 + amount * 0.23);
let column = floor(p.x / spacing + 0.5);
let seed = hash(vec2<f32>(column, 7.3));
let phase = fract(t * 0.19 * sqrt(gravity) + seed);
let fall = 2.4 - 4.8 * phase * phase;
let x = p.x - column * spacing;
let y = (fract((p.y - fall) / 4.8 + 0.5) - 0.5) * 4.8;
let angle = t * (seed - 0.5) * 1.7 + seed * 6.28318;
let q = vec2<f32>(cos(angle) * x - sin(angle) * y, sin(angle) * x + cos(angle) * y);
let radius = shape_size * (0.7 + 0.5 * seed);
let sides = select(3.0, 6.0, seed > 0.35);
let sector = 6.28318 / sides;
let a = atan2(q.y, q.x) + 3.14159;
let polygon = length(q) * cos(floor(a / sector + 0.5) * sector - a) - radius;
let square = max(abs(q.x), abs(q.y)) - radius * 0.86;
let d = select(polygon, square, seed > 0.72);
let fill = 1.0 - smoothstep(-0.012, 0.012, d);
let rim = exp(-abs(d) * 80.0);
let glow = exp(-max(d, 0.0) * 10.0);
let tint = mix(mix(c1, c2, seed), c3, 0.25 * sin(seed * 18.0) + 0.25);
let face = tint * (0.63 + 0.26 * clamp(q.y / radius + 0.5, 0.0, 1.0));
let backdrop = mix(c1, c3, 0.5 + 0.5 * sin(p.y * 0.6 + t * 0.12)) * 0.24;
let color = backdrop + tint * glow * 0.17 + face * fill + mix(c2, vec3<f32>(0.65, 0.87, 1.0), 0.35) * rim * 0.23;
return mix(bg, clamp(color, vec3<f32>(0.0), vec3<f32>(1.0)), strength);

let density = 1.1 + amount * 0.13;
let row = floor(p.y * density);
let seed = hash(vec2<f32>(row, 8.7));
let grid = vec2<f32>(p.x * density - t * (0.22 + gravity * 0.16) * (0.7 + seed * 0.6) + seed * 4.0, p.y * density);
let cell = floor(grid);
let id = hash(cell + vec2<f32>(3.1, 9.2));
let q = fract(grid) - vec2<f32>(0.5, 0.5 + sin(t * (2.0 + gravity) + cell.x * 3.0 + row) * 0.045);
let size = shape_size * (0.65 + id * 0.18);
let body = (length(q / vec2<f32>(size, size * 0.56)) - 1.0) * size * 0.56;
let tail = max(abs(q.y + sin(t * 7.0 + id * 9.0) * 0.025) - (-q.x - size * 0.55) * 0.65, max(-q.x - size * 1.65, q.x + size * 0.7));
let d = min(body, tail);
let fish = (1.0 - smoothstep(-0.008, 0.012, d)) * smoothstep(0.0, 0.8, amount);
let eye = 1.0 - smoothstep(size * 0.085, size * 0.13, length(q - vec2<f32>(size * 0.55, size * 0.15)));
let fishColor = mix(mix(c1, c2, id) * vec3<f32>(0.75 + 0.25 * sin(q.x / size * 15.0)), vec3<f32>(0.015, 0.04, 0.09), eye);
let water = cloud(p * vec2<f32>(1.4, 2.4) + vec2<f32>(t * 0.08, -t * 0.04));
let rays = pow(0.5 + 0.5 * sin(p.x * 4.5 + p.y * 1.3 + water * 5.0 + t * 0.3), 5.0);
let sea = mix(vec3<f32>(0.015, 0.13, 0.24), c1 * vec3<f32>(0.32, 0.48, 0.52), water) + c2 * vec3<f32>(rays * 0.18);
let halo = exp(-max(d, 0.0) * 18.0) * glow * 0.16 * smoothstep(0.0, 0.8, amount);
let color = mix(sea + mix(c2, c3, 0.25) * vec3<f32>(halo), fishColor, fish);
return mix(bg, clamp(color, vec3<f32>(0.0), vec3<f32>(1.0)), strength);

let density = 0.7 + amount * 0.24;
let column = floor(p.x * density);
let seed = hash(vec2<f32>(column, 7.3));
let phase = fract(t * gravity * 0.16 + seed);
let fall = 4.0 * phase * phase;
let grid = vec2<f32>(p.x * density, p.y * density + fall + seed * 5.0);
let cell = floor(grid);
let q = fract(grid) - vec2<f32>(0.5);
let angle = t * (seed - 0.5) * 1.5 + seed * 6.283;
let r = vec2<f32>(q.x * cos(angle) - q.y * sin(angle), q.x * sin(angle) + q.y * cos(angle));
let size = shape_size * (0.42 + seed * 0.14);
let circle = length(r) - size;
let square = max(abs(r.x), abs(r.y)) - size * 0.85;
let diamond = (abs(r.x) + abs(r.y)) * 0.7071 - size * 0.85;
let triangle = max(abs(r.x) * 0.866 + r.y * 0.5, -r.y) - size * 0.55;
let kind = fract(seed * 13.7);
let d = select(select(circle, square, kind > 0.25), select(diamond, triangle, kind > 0.75), kind > 0.5);
let fill = 1.0 - smoothstep(-0.012, 0.018, d);
let edge = exp(-abs(d) * 65.0);
let halo = exp(-max(d, 0.0) * 13.0) * (1.0 - fill);
let hue = fract(seed + cell.y * 0.117 + t * 0.035);
let neon = mix(palette(hue), mix(c1, c2, seed), 0.25);
let streak = exp(-abs(q.x) * 55.0) * smoothstep(-0.12, 0.42, q.y) * (0.2 + phase * 0.8);
let base = mix(bg, c3 * vec3<f32>(0.22, 0.26, 0.38), 0.6) + mix(c1, c2, 0.5) * vec3<f32>(0.035);
let activity = smoothstep(0.0, 0.5, amount);
let color = clamp(base + activity * (neon * (fill * 0.78 + halo * glow * 0.48 + streak * glow * 0.24) + mix(neon, c2, 0.35) * edge * 0.45), vec3<f32>(0.0), vec3<f32>(1.0));
return mix(bg, color, strength);

let plane = vec2<f32>(fract(t * 0.075 * flyby_speed) * 6.0 - 3.0, 0.48);
let proximity = exp(-plane.x * plane.x * 0.65);
let grain = hash(floor(p * vec2<f32>(460.0, 310.0)) + vec2<f32>(floor(t * 29.0)));
let bend = sin(p.y * 19.0 - t * 6.0) * 0.045 * proximity;
let signal = sin((p.x + bend) * 4.8 + p.y * 2.0 + t * 0.6);
let broadcast = mix(mix(c4, c1, smoothstep(-0.65, 0.65, signal)), mix(c2, c3, 0.5), 0.45 * smoothstep(0.1, 0.9, sin(p.x * 3.4 - p.y * 4.5 - t * 0.8)));
let ghost = ghost_strength * proximity * smoothstep(0.65, 0.95, sin((p.x + bend + 0.25) * 4.8 + p.y * 2.0 + t * 0.6));
let screen = broadcast * vec3<f32>((0.84 + 0.16 * sin(p.y * 430.0)) * (0.85 + (grain - 0.5) * static_amount * 0.7)) + c3 * vec3<f32>(ghost * 0.25);
let q = p - plane;
let aircraft = 1.0 - smoothstep(0.85, 1.2, min(length(q / vec2<f32>(0.19, 0.018)), abs(q.x + q.y * 0.34) / 0.037 + abs(q.y) / 0.15));
let a = p - vec2<f32>(0.78, -0.35);
let mast = (1.0 - smoothstep(0.009, 0.02, abs(a.x))) * (1.0 - smoothstep(0.48, 0.5, abs(a.y)));
let bars = (1.0 - smoothstep(0.04, 0.12, abs(fract((a.y + 0.02) * 9.0) - 0.5))) * (1.0 - smoothstep(0.12, 0.15, abs(a.x))) * (1.0 - smoothstep(0.3, 0.36, abs(a.y - 0.12)));
return mix(bg, clamp(mix(screen, c4 * vec3<f32>(0.16), max(aircraft, max(mast, bars)) * 0.93), vec3<f32>(0.0), vec3<f32>(1.0)), strength);

let drift = p * vec2<f32>(1.3, 1.8) + vec2<f32>(t * 0.045, t * 0.018);
let mist = cloud(drift);
let clouds = cloud(drift * vec2<f32>(2.1) + vec2<f32>(mist * 1.7, 0.0));
let horizon = exp(-abs(p.y + 0.55) * 1.6);
let sky = mix(c1, c2, clamp(mist * 0.8 + horizon * 0.25, 0.0, 1.0));
let atmosphere = sky * vec3<f32>(0.32 + clouds * 0.48) + c3 * vec3<f32>(horizon * 0.11);

let beat = t * lightning_rate;
let event = floor(beat * 0.5);
let seed = hash(vec2<f32>(event, 13.7));
let flash = pow(max(sin(beat * 6.28318), 0.0), 28.0);
let echo = pow(max(sin(beat * 6.28318 - 0.72), 0.0), 42.0) * 0.45;
let pulse = max(flash, echo);
let bolt_center = (seed - 0.5) * 2.8;
let jag = (noise(vec2<f32>(p.y * 18.0, event * 9.7)) - 0.5) * 0.22;
let bolt_x = bolt_center + sin(p.y * 5.5 + seed * 8.0) * 0.12 + jag;
let trunk = abs(p.x - bolt_x);
let branch_x = bolt_x + (0.28 - p.y) * 0.62;
let branch_gate = smoothstep(-0.85, -0.65, p.y) * (1.0 - smoothstep(0.2, 0.3, p.y));
let branch = exp(-abs(p.x - branch_x) * 135.0) * branch_gate;
let bolt = exp(-trunk * 180.0) + branch * 0.75;
let halo = exp(-trunk * 8.0);
let illumination = pulse * storm_glow;
let storm = atmosphere + c4 * vec3<f32>(illumination * (bolt * 1.35 + halo * 0.32 + clouds * 0.23));

let rain_uv = vec2<f32>(p.x + p.y * 0.19, p.y) * vec2<f32>(42.0 * rain_density, 5.5);
let lane = floor(rain_uv.x);
let rain_seed = hash(vec2<f32>(lane, 8.1));
let fall = fract(rain_uv.y + t * (2.8 + rain_seed * 2.0) + rain_seed * 12.0);
let width = abs(fract(rain_uv.x) - 0.5);
let streak = (1.0 - smoothstep(0.018, 0.075, width)) * smoothstep(0.48, 0.95, fall);
let rain = streak * (0.22 + rain_seed * 0.48) * step(0.24, rain_seed);
let rain_color = mix(c3, c4, rain_seed);
let color = storm + rain_color * vec3<f32>(rain * (0.8 + illumination)) + c5 * vec3<f32>(horizon * 0.035);
return mix(bg, clamp(color, vec3<f32>(0.0), vec3<f32>(1.0)), strength);

let time = t * storm_speed;
let drift = p * vec2<f32>(1.3, 1.8) + vec2<f32>(time * 0.09, time * 0.04);
let clouds = cloud(drift + vec2<f32>(cloud(drift), 0.0));
let billows = smoothstep(0.25, 0.8, clouds);
let sky = mix(c1, c2, billows) * vec3<f32>(0.55 + 0.38 * billows);
let horizon = exp(-abs(p.y + 0.65) * 1.6);
let atmosphere = mix(sky, c5, 0.17 * horizon);

let epoch = floor(time * 0.65);
let lane = floor((p.x + 1.4) / 2.8);
let seed = hash(vec2<f32>(lane, epoch));
let local_x = p.x - lane * 2.8;
let bolt_x = (seed - 0.5) * 1.6 + 0.14 * sin(p.y * 11.0 + seed * 30.0) + 0.07 * sin(p.y * 29.0 + seed * 17.0);
let bolt_distance = abs(local_x - bolt_x);
let flash_phase = fract(time * 0.65 + seed * 0.45);
let flash = pow(max(0.0, sin(flash_phase * 3.141593)), 18.0);
let flicker = 0.68 + 0.32 * sin(time * 63.0 + seed * 19.0);
let visibility = smoothstep(-1.3, -0.9, p.y) * (0.14 + flash * flicker);
let core = exp(-bolt_distance * 185.0);
let halo = exp(-bolt_distance * 14.0) * lightning_glow;
let branch_x = bolt_x + max(0.0, 0.35 - p.y) * 0.48 + 0.035 * sin(p.y * 42.0);
let branch = exp(-abs(local_x - branch_x) * 155.0) * smoothstep(-0.7, -0.4, p.y) * (1.0 - smoothstep(0.25, 0.4, p.y));
let lightning = c4 * vec3<f32>((core + branch * 0.55) * visibility) + c3 * vec3<f32>(halo * visibility * 0.65);

let rain_uv = vec2<f32>((p.x + p.y * 0.18) * 43.0 * rain_density, p.y * 9.0 + time * 10.0);
let rain_cell = floor(rain_uv);
let rain_random = hash(rain_cell);
let rain_pos = fract(rain_uv);
let streak = exp(-abs(rain_pos.x - 0.5) * 48.0) * smoothstep(0.05, 0.25, rain_pos.y) * (1.0 - smoothstep(0.55, 0.95, rain_pos.y));
let rain = streak * step(0.43, rain_random) * (0.35 + rain_random * 0.65);
let color = atmosphere + lightning + c3 * vec3<f32>(rain * 0.65) + c2 * vec3<f32>(flash * 0.16 * billows);
return mix(bg, clamp(color, vec3<f32>(0.0), vec3<f32>(1.0)), strength);

let x = clamp(p.x * 0.35 + 0.5, 0.0, 1.0);
let y = clamp(p.y * 0.5 + 0.5, 0.0, 1.0);
let ramp = smoothstep(0.0, 1.0, mix(x, y, tilt));
let low = mix(c1, c2, ramp);
let high = mix(c3, c4, y * 0.25);
let color = mix(low, high, ramp * depth);
return mix(bg, mix(color, c5, ramp * ramp * 0.08), strength);

let sky = mix(c1, c2, smoothstep(-0.5, 0.5, p.y)) * 0.9;
let st = stars(p * 22.0, t) + stars(p * 38.0 + vec2<f32>(11.0, 3.0), t * 0.7) * 0.6;
let moon = vec2<f32>(0.42, 0.22);
let md = sd_circle(p - moon, moon_size);
let maria = 0.85 + 0.15 * noise(p * 30.0);
let disk = fill(md) * c4 * maria;
let moon_glow = c3 * halo(md, 0.3) * 0.35;
let moon_light = 1.0 / (1.0 + 4.0 * dot(p - moon, p - moon));
let far_n = cloud(p * vec2<f32>(1.2, 1.8) + vec2<f32>(t * cloud_speed * 0.2, 3.0));
let near_n = cloud(p * vec2<f32>(2.4, 3.0) + vec2<f32>(t * cloud_speed, 7.0));
let far_mask = smoothstep(0.45, 0.8, far_n) * 0.55;
let near_mask = smoothstep(0.5, 0.8, near_n) * 0.85;
let far_col = mix(c2 * 0.7, c5, 0.35) + c3 * moon_light * 0.25;
let near_col = mix(c1 * 0.6, c2, 0.6) + c5 * moon_light * 0.4 + c4 * moon_light * 0.15;
let cyc = t * 0.12;
let cid = floor(cyc);
let cf = fract(cyc);
let cstart = vec2<f32>(hash(vec2<f32>(cid, 2.0)) * 1.6 - 0.6, 0.6);
let cdir = normalize(vec2<f32>(-1.0, -0.5));
let head = cstart + cdir * cf * comet_speed * 1.2;
let vis = 1.0 - smoothstep(0.5, 0.7, cf);
let seg = sd_segment(p, head, head - cdir * 0.35);
let tail = halo(seg, 0.035) * vis * 0.6 * c3;
let head_glow = (fill(sd_circle(p - head, 0.008)) + halo(sd_circle(p - head, 0.008), 0.03) * 0.6) * vis * c4;
let scene0 = sky + st * c4 * 0.8 + disk + moon_glow;
let scene1 = mix(scene0, far_col, far_mask);
let scene2 = mix(scene1, near_col, near_mask);
let scene = scene2 + tail + head_glow;
return mix(bg, tonemap(scene), strength);

let up = p.y + 0.5;
let speed = flame_speed * t;
let nf = cloud(vec2<f32>(p.x * 2.0 + 3.1 + t * 0.04, up * 1.3 - speed * 0.4));
let af = smoothstep(0.3, 0.7, nf - up * 0.55);
let far_col = mix(c1 * 0.6, c1, af);
let nm = flow(vec2<f32>(p.x * 2.8 - t * 0.06, up * 1.7 - speed * 0.7), t * 0.4);
let am = smoothstep(0.28, 0.62, nm - up * 0.6);
let mid_col = mix(c1, c2, smoothstep(0.2, 0.7, am));
let nn = flow(vec2<f32>(p.x * 3.6 + t * 0.02, up * 2.2 - speed), t * 0.6);
let an = smoothstep(0.3, 0.6, nn * 1.1 - up * 0.7);
let near_core = smoothstep(0.55, 0.95, an);
let near_col = mix(mix(c1, c2, an), c3, near_core);
let glow = smoothstep(0.6, -0.5, up);
let base = mix(bg, c4, glow * 0.9) + c1 * glow * 0.25;
let s1 = mix(base, far_col, af * 0.55);
let s2 = mix(s1, mid_col, am * 0.8);
let s3 = mix(s2, near_col, an);
let sp = stars(vec2<f32>(p.x * 14.0, p.y * 9.0 - speed * 1.5), t * 2.0);
let fade = 1.0 - smoothstep(0.2, 0.7, up);
let scene = s3 + c3 * sp * ember_density * fade;
return mix(bg, tonemap(scene * 1.2), strength);

let w = sin(p * (4.0 + wobble * 2.0) + vec2<f32>(t * 1.4, t * 1.1));
let q = p * blob_scale + vec2<f32>(w.y, w.x) * wobble * 0.5;
let veins = ridged(q + vec2<f32>(0.0, t * 0.2));
let ridge = smoothstep(0.55, 0.9, veins);
let edge = 1.0 - smoothstep(0.0, 0.05, abs(veins - 0.7));
let q2 = p * blob_scale * 0.5 + vec2<f32>(t * 0.05, -t * 0.03) + vec2<f32>(w.x, w.y) * 0.2;
let deep = ridged(q2);
let pulse = pow(0.5 + 0.5 * sin(t * beat * 6.2832), 4.0);
let slow = 0.5 + 0.5 * sin(t * 0.4);
let back = mix(c4, c2, smoothstep(0.3, 0.8, deep)) * (0.7 + 0.3 * slow);
let blob = mix(c5, c1, ridge);
let glint = c3 * edge * (0.5 + 0.9 * pulse);
