let radius = ball_size * facet;
let mask = 1.0 - smoothstep(radius - 0.006, radius + 0.006, length(q));
let spin = angle + t * bounce_speed * (1.2 + seed) + seed * 12.0;
let panel = floor(fract(spin / 6.28318) * 6.0);
let warm = mix(c1, c2, vec3<f32>(step(0.5, panel)));
let cool = mix(c3, c4, vec3<f32>(step(3.5, panel)));
let stripes = mix(mix(warm, cool, vec3<f32>(step(1.5, panel))), c5, vec3<f32>(step(4.5, panel)));
let lighting = clamp(0.86 + dot(q / vec2<f32>(ball_size), vec2<f32>(-0.22, 0.28)), 0.5, 1.0);
let seam = pow(abs(sin(spin * 3.0)), 0.16);
let ball = stripes * vec3<f32>(lighting * (0.72 + 0.28 * seam));
let shadow_q = (p - vec2<f32>(lane * 1.05 + drift, -0.59)) / vec2<f32>(ball_size * (1.0 + lift * 0.4), 0.045);
let shadow = exp(-dot(shadow_q, shadow_q) * 1.8) * (0.4 / (1.0 + lift));
let ground = mix(scenery, c5, vec3<f32>(shadow));
let color = mix(ground, ball, vec3<f32>(mask));
return mix(bg, clamp(color, vec3<f32>(0.0), vec3<f32>(1.0)), vec3<f32>(strength));

let shore = -0.68 + 0.025 * sin(p.x * 2.4 + t * 0.35);
let sand = 1.0 - smoothstep(shore - 0.03, shore + 0.03, p.y);
let sea = 1.0 - smoothstep(-0.37, -0.22, p.y);
let sky_color = mix(bg, c4, 0.32 + 0.12 * exp(-abs(p.y + 0.2) * 1.5));
let water_color = mix(c4, c3, 0.32 + 0.08 * sin(p.x * 3.0 + p.y * 22.0 + t * 0.5));
let sand_color = c5 * vec3<f32>(0.55);
let landscape = mix(mix(sky_color, water_color, sea), sand_color, sand);
let ripple = pow(0.5 + 0.5 * sin(p.y * 65.0 + sin(p.x * 3.0 + t * 0.3) - t * 0.8), 12.0);
let ground = landscape + c3 * vec3<f32>(ripple * sea * (1.0 - sand) * 0.045);
let lane = floor((p.x + 0.48) / 0.96);
let seed = hash(vec2<f32>(lane, 7.0));
let radius = ball_size * (0.8 + 0.2 * seed);
let phase = fract(t * bounce_speed * 0.55 + seed);
let lift = bounce_height * 4.0 * phase * (1.0 - phase);
let center_x = lane * 0.96 + 0.06 * sin(t * 0.45 + seed * 6.28);
let center_y = -0.69 + radius + lift;
let q = (p - vec2<f32>(center_x, center_y)) / vec2<f32>(radius);
let angle = atan2(q.y, q.x) + t * (0.45 + seed * 0.35);
let face_angle = (fract(angle / 6.283185 * 10.0 + 0.5) - 0.5) * 0.628319;
let polygon = length(q) * cos(face_angle);
let mask = 1.0 - smoothstep(0.94, 1.0, polygon);
let sector = floor(fract(angle / 6.283185) * 6.0);
let panel = 0.5 + 0.5 * sin(sector * 2.094395 + seed * 2.0);
let ball_color = mix(mix(c1, c2, panel), c3, step(0.65, panel));
let lighting = clamp(0.83 + 0.13 * q.y - 0.09 * q.x, 0.55, 1.0);
let seam = 1.0 - smoothstep(0.0, 0.035, abs(sin(angle * 3.0)));
let ball = ball_color * vec3<f32>(lighting * (1.0 - seam * 0.18));
let shadow = exp(-pow((p.x - center_x) / (radius * 1.3), 2.0) - pow((p.y + 0.70) / 0.035, 2.0)) * 0.24 / (1.0 + lift * 2.0);
let color = mix(ground * vec3<f32>(1.0 - shadow), ball, mask);
return mix(bg, clamp(color, vec3<f32>(0.0), vec3<f32>(1.0)), strength);

let r = length(p);
let angle = atan2(p.y, p.x);
let sector = (angle + 3.141593) * 120.0 / 6.283186;
let lane = floor(sector);
let seed = hash(vec2<f32>(lane, 17.0));
let offset = 0.2 + 0.6 * hash(vec2<f32>(lane, 31.0));
let filament = exp(-pow(abs(fract(sector) - offset) * 13.0, 2.0));
let phase = fract(r * r * 0.65 + t * warp_speed * (0.3 + seed * 0.55) + seed);
let tail = pow(phase, 12.0);
let head = exp(-pow((phase - 0.94) * 38.0, 2.0));
let streaks = filament * (0.65 * tail + 0.65 * head) * (0.35 + 0.65 * seed);
let bend = 0.035 * sin(angle * 5.0 + t * 0.37) + 0.018 * sin(angle * 9.0 - t * 0.23);
let ring_radius = 0.39 + 0.025 * sin(t * 0.9);
let ring_distance = abs(r - ring_radius - bend);
let ring = exp(-ring_distance * 45.0) * ring_glow * (0.6 + 0.4 * sin(angle * 3.0 + t * 0.6));
let haze = cloud(p * 1.6 + vec2<f32>(t * 0.025, -t * 0.018));
let atmosphere = mix(c1, c3, 0.3 + 0.4 * haze) * (0.19 + 0.19 * haze);
let star_color = mix(c1, c2, seed);
let outer = atmosphere + star_color * streaks + mix(c3, c4, 0.3) * ring * 0.65;
let aperture = smoothstep(0.14, 0.29, r);
let color = clamp(outer * aperture, vec3<f32>(0.0), vec3<f32>(1.0));
return mix(bg, color, strength);

let x = p.x * frequency;
let phase = x - t * 1.3;
let fundamental = sin(phase);
let overtone = sin(x * harmonic_ratio + t * 1.1);
let beat = sin(x * 0.47 - t * 0.6);
let y1 = 0.46 * fundamental + 0.14 * overtone;
let y2 = 0.46 * overtone - 0.14 * fundamental;
let y3 = 0.32 * sin(phase + overtone * 1.6) + 0.23 * beat;
let d1 = abs(p.y - y1);
let d2 = abs(p.y - y2);
let d3 = abs(p.y - y3);
let ribbon1 = exp(-pow(d1 / ribbon_width, 2.0));
let ribbon2 = exp(-pow(d2 / ribbon_width, 2.0));
let ribbon3 = exp(-pow(d3 / (ribbon_width * 0.75), 2.0));
let halo = exp(-d1 * 3.0) + exp(-d2 * 3.0) + exp(-d3 * 3.0);
let weave = 0.5 + 0.5 * sin(x * 0.55 + p.y * 2.3 + t * 0.3);
let base = mix(c4, c1, weave) * vec3<f32>(0.24 + 0.08 * beat);
let bead_x = (fract((x - t * 1.3) / 6.283185 + 0.25) - 0.5) * 6.283185 / frequency;
let beads = exp(-(bead_x * bead_x + d1 * d1) / 0.008);
let stripes = 0.82 + 0.18 * sin(p.y * 70.0 + x * 3.0 - t * 4.0);
let color = base + mix(c1, c4, weave) * vec3<f32>(halo * 0.11)
    + c1 * vec3<f32>(ribbon1 * stripes * 0.68)
    + c2 * vec3<f32>(ribbon2 * stripes * 0.68)
    + c3 * vec3<f32>(ribbon3 * 0.65)
    + c5 * vec3<f32>(beads * 0.5);
return mix(bg, clamp(color, vec3<f32>(0.0), vec3<f32>(1.0)), strength);

let x = p.x * frequency;
let phase = x - t * 1.3;
let overtone = sin(phase * 2.0 + t * 0.35) * 0.12 + sin(phase * 3.0 - t * 0.2) * 0.06;
let wave_a = sin(phase) * 0.23 + overtone * harmonic_mix;
let wave_b = sin(x * 1.25 + t * 1.05) * 0.22 + sin(x * 2.5 + t * 0.8) * harmonic_mix * 0.1;
let wave_c = (wave_a + wave_b) * 0.65;
let da = abs(p.y - 0.58 - wave_a);
let db = abs(p.y + 0.58 - wave_b);
let dc = abs(p.y - wave_c);
let trace_a = exp(-da * 80.0) + exp(-da * 12.0) * 0.3 * glow;
let trace_b = exp(-db * 80.0) + exp(-db * 12.0) * 0.3 * glow;
let trace_c = exp(-dc * 70.0) + exp(-dc * 10.0) * 0.4 * glow;
let beat = 0.5 + 0.5 * sin(x * 0.25 + t * 0.55);
let interference = 0.5 + 0.5 * sin(p.y * 9.0 + sin(phase) * 1.8 + sin(x * 1.25 + t) * 1.5);
let field = mix(c2, c3, interference) * vec3<f32>(0.25 + 0.13 * beat);
let grid_x = pow(0.5 + 0.5 * cos(p.x * 24.0), 24.0);
let grid_y = pow(0.5 + 0.5 * cos(p.y * 24.0), 24.0);
let grid = c1 * vec3<f32>((grid_x + grid_y) * 0.035);
let signal_a = c1 * vec3<f32>(trace_a * 0.8);
let signal_b = c3 * vec3<f32>(trace_b * 0.8);
let signal_c = mix(c4, c5, beat) * vec3<f32>(trace_c * 0.85);
let color = clamp(field + grid + signal_a + signal_b + signal_c, vec3<f32>(0.0), vec3<f32>(1.0));
return mix(bg, color, strength);

let moon_p = vec2<f32>(0.32, 0.24);
let md = sd_circle(p - moon_p, moon_size);
let moon = fill(md) * c4 * 1.1 + halo(md, 0.22) * c4 * 0.35 + halo(md, 0.05) * c3 * 0.3;
let warm = c4 * 0.5 * (1.0 - smoothstep(-0.08, 0.4, p.y));
let sky_base = mix(c5 * 0.55, c1 * 0.5, smoothstep(-0.08, 0.5, p.y));
let stars_l = stars(p * 26.0 * star_density, t) * smoothstep(-0.02, 0.1, p.y);
let sky = sky_base + warm + moon + c3 * stars_l;
var col = sky;
for (var i = 0; i < 3; i++) {
    let k = f32(i);
    let top = -0.08 - 0.13 * k;
    let dd = max(top - p.y, 0.0) + 0.03;
    let z = (0.1 + 0.08 * k) / dd;
    let wx = p.x * z;
    let n1 = noise(vec2<f32>(wx * 0.9 + t * 0.2, z * 0.6 - t * 0.4 + k * 3.0));
    let n2 = noise(vec2<f32>(wx * 1.9 - t * 0.35, z * 1.4 + t * 0.7 + k * 5.0));
    let h = n1 * 0.6 + n2 * 0.4 * wave_height;
    let crest = smoothstep(0.55, 0.9, h);
    let trough = 1.0 - smoothstep(0.25, 0.55, h);
    let base = mix(c1, c2, 0.35 + 0.3 * k);
    let body = mix(base * 0.5, base * 1.3, crest) * (1.0 - 0.3 * trough);
    let refl_x = p.x - moon_p.x + (n2 - 0.5) * 0.15 * wave_height;
    let streak = exp(-abs(refl_x) * 7.0) * crest;
    let layer = body + c3 * crest * 0.25 + c4 * streak * 0.9;
    let mask = 1.0 - smoothstep(top - 0.004, top + 0.004, p.y);
    col = mix(col, layer, mask);
}
return mix(bg, tonemap(col * 1.15), strength);

let hz = -0.03;
let below = max(hz - p.y, 0.015);
let depth = 1.0 / below;
let px = p.x * depth;
let fog = exp(-below * 2.5);
let w1 = noise(vec2<f32>(px * 0.8 + t * 0.15 * wave_speed, depth * 2.0 - t * 0.5 * wave_speed));
let w2 = noise(vec2<f32>(px * 1.7 - t * 0.25 * wave_speed, depth * 4.0 + t * 0.7 * wave_speed));
let ripple = w1 * 0.6 + w2 * 0.4;
let crest = smoothstep(0.55, 0.8, ripple);
let glint_x = p.x - 0.42 + (w2 - 0.5) * 0.12 * (1.0 + depth * 0.2);
let glint = smoothstep(0.1, 0.0, abs(glint_x)) * (0.3 + 0.7 * fog) * (0.5 + 0.5 * crest);
let water = mix(c1 * 0.7, c2, ripple) * (0.5 + 0.5 * fog) + c3 * crest * 0.3 + c4 * glint * 0.7;
let stars_v = stars(p * 22.0, t);
let sky = mix(c5 * 0.45, c1 * 0.3, smoothstep(hz, 0.5, p.y));
let moon_d = sd_circle(p - vec2<f32>(0.42, 0.3), 0.05);
let moon = fill(moon_d) + halo(moon_d, 0.2) * 0.4;
let skyc = sky + c3 * stars_v * 0.8 + c4 * moon;
let foam = smoothstep(0.02, 0.0, abs(p.y - hz)) * (0.4 + 0.6 * ripple) * c3;
let scene = mix(water + foam, skyc, smoothstep(hz - 0.004, hz + 0.004, p.y));
return mix(bg, tonemap(scene), strength);

let wide = vec2<f32>(p.x * 2.5, p.y * 8.0 + t * ripple_speed * 0.15);
let band = sin(wide.y * 3.14159 * 0.8) * 0.25;
let ripple = fbm(wide + vec2<f32>(band * 1.5 + t * 0.03, sin(wide.x * 0.7 + t * 0.2) * 0.4) * ripple_scale);
let banded = fract(ripple * 4.0 + p.y * 6.0 + t * 0.1);
let glow = smoothstep(0.3, 0.85, banded);
let gold = mix(c1, c2, smoothstep(0.2, 0.8, ripple));
let orange = mix(c3, c4, smoothstep(0.4, 1.0, glow) * 0.7);
let metal = mix(gold * 1.2, orange * 1.4, smoothstep(0.5, 0.9, ripple * 1.3));

let static_noise = hash(floor(p * 80.0 + vec2<f32>(t * 3.0, 7.0)));
let tape = 1.0 - 0.35 * smoothstep(0.0, 1.0, abs(fract(p.y * 3.0 + t * 0.02) - 0.5) * 2.0);
let static_band = mix(1.0, 0.85 + 0.15 * static_noise, static_glow) * tape;
let shimmer = 1.0 + 0.2 * sin(t * 0.7 + ripple * 12.0);

let color = tonemap(metal * shimmer * static_band * 1.3);
return mix(bg, color, strength);

let sc = 5.0 * cell_density;
let cells = voronoi(p * sc + vec2<f32>(t * 0.04, t * 0.02));
let seed = cells.z;
let angle = seed * 6.28318;

// Neon border oscillates between cyan and magenta per cell
let bpulse = 0.5 + 0.5 * sin(t * pulse_speed * 2.0 + angle);
let neon = mix(c2, c1, bpulse);

// Fill: saturated tint unique to each cell, drifting over time
let fc = 0.5 + 0.5 * sin(t * 0.3 * fill_anim + angle * 1.7);
let fill_col = mix(mix(c4, c3, seed), mix(c1, c5, seed), fc);

// Backlight: brightest at the cell's center
let core_light = 0.75 + 0.25 * exp(-cells.x * 6.0);

// Border: crisp neon line plus a soft aura
let line = 1.0 - smoothstep(0.0, 0.04, cells.y);
let aura = exp(-cells.y * 16.0) * 0.5 * border_glow;

let color = fill_col * core_light * 1.15 + neon * (line * 0.85 + aura);
return mix(bg, tonemap(color), strength);

let horizon = 0.10;
let up = p.y - horizon;
let ground = max(-up, 0.0);
let below = smoothstep(0.0, 0.02, -up);

// night sky with a warm band along the horizon
let skyT = smoothstep(0.0, 0.62, up);
let skyCol = mix(c1 * 0.55, c3 * 0.45, skyT) + c4 * stars(p * 24.0, t) * smoothstep(0.05, 0.30, up) * 0.9;

// perspective floor
let depth = 1.0 / max(horizon - p.y, 0.05);
let u = p.x * depth * 2.2;
let v = depth * 0.9 - t * 0.55;
let w = vec2<f32>(noise(vec2<f32>(u * 0.45, v * 0.45)), noise(vec2<f32>(u * 0.45 + 31.0, v * 0.45))) - 0.5;
let gu = (u + w.x * wobble * 0.25) * density;
let gv = (v + w.y * wobble * 0.25) * density;
let cell = floor(vec2<f32>(gu, gv));
let f = fract(vec2<f32>(gu, gv)) - 0.5;
let seed = hash(cell);
let fade = 1.0 - smoothstep(9.0, 16.0, depth);

// hand-drawn tile borders
let edge = 0.5 - max(abs(f.x), abs(f.y));
let lw = 0.02 + 0.012 * depth;
let gridline = 1.0 - smoothstep(0.0, lw, edge);

// one small window per tile
let off = (hash2(cell + vec2<f32>(3.7, 1.3)) - 0.5) * 0.24;
let size = vec2<f32>(0.17, 0.11 + 0.05 * seed);
let d = sd_box(f - off, size);
let flick = 1.0 - flicker * (0.5 + 0.5 * sin(t * (0.9 + 2.6 * seed) + seed * 6.28318));
let lit = step(0.2, seed);
let pick = hash(cell + vec2<f32>(9.1, 4.4));
let tint = mix(c1, c4, pick * pick);
let win = (fill(d) * 0.95 + halo(d, 0.11) * 0.5) * flick * lit * fade * glow;

// floor surface
let floorBase = mix(c3, c2 * 0.45, 0.30 + 0.40 * (w.x + 0.5)) * 0.95;
let haze = c1 * 0.42 * exp(-ground * 7.0);
let floorCol = floorBase + haze + mix(c2, c4, 0.25) * gridline * 0.5 * fade + tint * win;

let scene = mix(skyCol, floorCol, below);
return mix(bg, tonemap(scene * 1.15), strength);

let dir = normalize(vec2<f32>(0.82, -0.57));
let perp = vec2<f32>(-dir.y, dir.x);
let tex = ridged(vec2<f32>(dot(p, perp) * 8.0, dot(p, dir) * 2.0 - t * 1.8));
var acc = vec3<f32>(0.0);

for (var i = 0; i < 5; i++) {
    let k = f32(i);
    let s1 = hash(vec2<f32>(k, 2.3));
    let s2 = hash(vec2<f32>(k, 9.1));
    let ph = fract(t * (0.20 + 0.22 * s2) * comet_speed + s1);
    let lane = -0.75 + 1.5 * s2 + 0.08 * sin(t * 0.4 + k * 1.9);
    let head = perp * lane + dir * (ph * 3.8 - 1.9);
    let rel = p - head;
    let along = dot(rel, dir);
    let acr = dot(rel, perp);
    let w = 0.011 + 0.010 * s1;
    let tlen = tail_length * (0.8 + 0.7 * s2);
    let acn = acr / w;
    let back = max(-along, 0.0);
    let body = exp(-acn * acn) * exp(-back * 2.3 / tlen) * exp(-max(along, 0.0) * 26.0);
    let hot = exp(-dot(rel, rel) * 85.0);
    let u = clamp(back / tlen, 0.0, 1.0);
    let tint = mix(mix(c4, c1, smoothstep(0.0, 0.25, u)), c2, smoothstep(0.25, 1.0, u));
    acc += tint * (body + hot * 2.0);
}

let pf = p * 2.0 + vec2<f32>(3.7, 1.3);
for (var j = 0; j < 5; j++) {
    let m = f32(j);
    let m1 = hash(vec2<f32>(m, 4.7));
    let m2 = hash(vec2<f32>(m, 12.9));
    let phb = fract(t * (0.10 + 0.12 * m2) * comet_speed + m1);
    let lane2 = -0.85 + 1.7 * m2 + 0.06 * sin(t * 0.25 + m * 2.4);
    let head2 = perp * lane2 + dir * (phb * 3.6 - 1.8);
    let rel2 = pf - head2;
    let along2 = dot(rel2, dir);
    let acr2 = dot(rel2, perp);
    let w2 = 0.012 + 0.008 * m1;
    let tlen2 = tail_length * (0.6 + 0.5 * m2);
    let acn2 = acr2 / w2;
    let back2 = max(-along2, 0.0);
    let body2 = exp(-acn2 * acn2) * exp(-back2 * 2.6 / tlen2) * exp(-max(along2, 0.0) * 26.0);
    let hot2 = exp(-dot(rel2, rel2) * 110.0);
    let u2 = clamp(back2 / tlen2, 0.0, 1.0);
    let tint2 = mix(mix(c3, c2, smoothstep(0.0, 0.6, u2)), c5 * 1.8, smoothstep(0.5, 1.0, u2));
    acc += tint2 * body2 * 0.65 + c2 * hot2 * 0.7;
}

let veil = mix(c3, c2, tex) * tex * tex * 0.55;
let wash = mix(c3 * 0.14, c2 * 0.07, smoothstep(-0.5, 0.5, p.y));
let sharp = 0.55 + 0.85 * tex;
let vign = 0.78 + 0.22 * (1.0 - smoothstep(0.45, 1.15, length(p)));
let scene = (wash + veil + acc * sharp * glow) * vign;
return mix(bg, tonemap(scene * 1.45), strength);

let horizon = -0.12;
let dy = max(horizon - p.y, 0.0);
let z = 0.06 + dy * 1.1;

// swaying stalks, spacing tightens toward the horizon
let sway = sin(t * 0.30 + p.y * 6.5) * 0.20 + sin(t * 0.13 + p.x * 1.7) * 0.10;
let gx = p.x * (1.5 / z) + sway * 2.0;
let stalk = (1.0 - smoothstep(0.0, 0.17, abs(fract(gx) - 0.5))) * smoothstep(0.0, 0.07, dy);

// row crests drifting at two different speeds
let rA = ridged(vec2<f32>(p.x * 2.0 + sway * 0.8, p.y * 8.5 - t * 0.05));
let rB = ridged(vec2<f32>(p.x * 4.2 - t * 0.08, p.y * 14.0 + 5.3));
let rows = rA * 0.62 + rB * 0.42;

let haze = exp(-abs(p.y - horizon) * 7.0);
let sunPos = vec2<f32>(0.18 + 0.04 * sin(t * 0.05), -0.05);
let sunD = sd_circle(p - sunPos, 0.05);
let sun = halo(sunD, 0.22) * 0.65 + fill(sunD) * 0.60;

let up = smoothstep(horizon, 0.48, p.y);
let sky = mix(c2 * 0.95, c3 * 0.72, up) + c4 * haze * 0.32 + mix(c2, c4, 0.6) * sun;

let tone = clamp(rows * 0.8 + stalk * 0.6, 0.0, 1.0);
let field = mix(c5, c1, tone) + c2 * (stalk * 0.15 + smoothstep(0.55, 0.95, rA) * 0.22) + c4 * haze * 0.26;

let mask = smoothstep(horizon - 0.02, horizon + 0.02, p.y);
let scene = mix(field, sky, mask);
return mix(bg, tonemap(scene * 1.2), strength);

let n1 = fbm(p * 1.7 + vec2<f32>(t * 0.035, -t * 0.02));
let warp = fbm(p * 2.4 + vec2<f32>(n1 * 1.8 - t * 0.03, n1 * 1.5 + t * 0.045));
let fil = smoothstep(0.28, 0.78, warp);
let band = 0.5 + 0.5 * sin(n1 * 6.28318 + warp * 5.0 - t * 0.22);
let flowc = mix(c2, c1, smoothstep(0.22, 0.86, warp));
let depth = smoothstep(-0.65, 0.65, p.y);
let base = mix(c4 * 0.45, c2 * 0.5, depth);
let currents = flowc * (0.16 + 0.62 * fil) * (0.55 + 0.45 * band);
let phase = p.x * 6.5 + 1.1 * sin(p.y * 2.0 - t * 0.22) + n1 * 3.2 + t * 0.06;
let shaft = pow(abs(sin(phase)), 8.0);
let ripple = 0.7 + 0.3 * sin(p.y * 11.0 - t * 1.0 + p.x * 4.0);
let beams = shaft * ripple * smoothstep(-0.5, 0.55, p.y);
let g = p * 8.0 + vec2<f32>(t * 0.06, t * 0.10);
let cell = floor(g);
let seed = hash(cell);
let off = vec2<f32>(0.20 * sin(t * 0.45 + seed * 6.28), 0.20 * cos(t * 0.35 + seed * 4.71));
let d = sd_circle(fract(g) - 0.5 - off, 0.015 + 0.028 * seed);
let pulse = 0.45 + 0.55 * (0.5 + 0.5 * sin(t * 1.1 + seed * 30.0));
let spark = step(0.40, hash(cell + vec2<f32>(5.0, 11.0))) * pulse * (0.45 + 0.75 * seed);
let near_pl = halo(d, 0.085) * spark;
let g2 = p * 15.0 - vec2<f32>(t * 0.025, t * 0.045);
let cell2 = floor(g2);
let seed2 = hash(cell2 + vec2<f32>(19.0, 7.0));
let d2 = sd_circle(fract(g2) - 0.5, 0.010 + 0.020 * seed2);
let pulse2 = 0.35 + 0.65 * (0.5 + 0.5 * sin(t * 0.8 + seed2 * 25.0));
let far_pl = halo(d2, 0.055) * pulse2 * step(0.58, hash(cell2 + vec2<f32>(3.0, 29.0)));
let plankton = near_pl * mix(c3, c1, seed) + far_pl * mix(c2, c5, seed2) * 0.7;
let col = base + currents * 0.9 + beams * mix(c1, c3, 0.4) * 0.55 + plankton * 1.1;
return mix(bg, tonemap(col * 1.1), strength);

let tw = t * wave_speed;
let base = mix(c4 * 0.35, c2 * 0.45, smoothstep(-0.5, 0.5, p.y));
let w1 = 0.34 + 0.03 * sin(p.x * 4.0 + tw * 0.5);
let w2 = 0.2 + 0.035 * sin(p.x * 6.5 - tw * 0.8 + 1.3);
let w3 = 0.06 + 0.04 * sin(p.x * 10.0 + tw * 1.3 + 2.1);
let m1 = smoothstep(-0.008, 0.008, p.y - w1);
let m2 = smoothstep(-0.008, 0.008, p.y - w2);
let m3 = smoothstep(-0.008, 0.008, p.y - w3);
let layer1 = mix(base, c2 * 0.8, m1 * 0.35);
let layer2 = mix(layer1, c5 * 0.6, m2 * 0.4);
let edge3 = 1.0 - smoothstep(0.0, 0.014, abs(p.y - w3));
let layer3 = mix(layer2, c3, m3 * 0.25) + c3 * edge3 * 0.5;
let rays = pow(0.5 + 0.5 * sin(p.x * 9.0 + sin(p.y * 3.0 + tw * 0.3) * 2.0), 6.0) * smoothstep(-0.2, 0.5, p.y);
let light = layer3 + c3 * rays * 0.25;
let thr = clamp(1.0 - 0.35 * bubble_amount, 0.0, 1.0);
let ga = vec2<f32>(p.x * 7.0, p.y * 7.0 - t * 0.12);
let ca = floor(ga);
let sa = hash(ca);
let ja = (hash2(ca) - vec2<f32>(0.5, 0.5)) * 0.5;
let da = sd_circle(fract(ga) - 0.5 - ja, 0.12 + 0.04 * sa);
let fa = stroke(da, 0.025) * step(thr, sa) * 0.5;
let gb = vec2<f32>(p.x * 4.5, p.y * 4.5 - t * 0.25);
let cb = floor(gb);
let sb = hash(cb);
let jb = (hash2(cb) - vec2<f32>(0.5, 0.5)) * 0.5;
let db = sd_circle(fract(gb) - 0.5 - jb, 0.16);
let fb = (stroke(db, 0.03) + fill(db) * 0.08) * step(thr, sb);
let gc = vec2<f32>(p.x * 2.5, p.y * 2.5 - t * 0.4);
let cc = floor(gc);
let sc = hash(cc);
let jc = (hash2(cc) - vec2<f32>(0.5, 0.5)) * 0.5;
let dc = sd_circle(fract(gc) - 0.5 - jc, 0.2);
let fc = (stroke(dc, 0.035) + fill(dc) * 0.08 + halo(dc, 0.03) * 0.15) * step(thr, sc);
let bubbles = c2 * fa + c1 * fb * 0.8 + c3 * fc * 1.2;
let total = tonemap(light + bubbles);
return mix(bg, total, strength);

let tt = t * bubble_speed;
let depth = smoothstep(0.5, -0.5, p.y);
let w1 = 0.34 + 0.05 * wave_amp * sin(p.x * 5.0 + t * 0.9) + 0.02 * wave_amp * sin(p.x * 12.0 - t * 1.5);
let w2 = 0.05 + 0.07 * wave_amp * sin(p.x * 3.5 - t * 0.6 + 1.3);
let w3 = -0.22 + 0.08 * wave_amp * sin(p.x * 2.2 + t * 0.45 + 2.7);
let air = smoothstep(w1 - 0.01, w1 + 0.01, p.y);
let water = mix(c1 * 0.45 + c4 * 0.12, c2 * 0.4 + c4 * 0.05, depth);
let air_col = mix(c3 * 0.7, c1 * 0.9, smoothstep(0.5, 0.2, p.y));
let surfc = mix(water, air_col, air);
let glint = exp(-abs(p.y - w1) * 34.0) * c3;
let band2 = exp(-abs(p.y - w2) * 22.0) * c1 * 0.5;
let band3 = exp(-abs(p.y - w3) * 16.0) * c5 * 0.25;
let caustic = ridged(p * vec2<f32>(6.0, 4.0) + vec2<f32>(t * 0.08, t * 0.05)) * (1.0 - depth) * c3 * 0.25;
let fa = vec2<f32>(p.x * 14.0, p.y * 14.0 - tt * 0.25);
let ca = floor(fa);
let sa = hash(ca + vec2<f32>(3.0, 1.0));
let la = fract(fa) - 0.5 - (hash2(ca) - 0.5) * 0.3 + vec2<f32>(0.06 * sin(tt * 1.3 + sa * 6.28), 0.0);
let da = sd_circle(la, (0.1 + 0.06 * sa) * bubble_size);
let ba = (stroke(da, 0.03) + fill(da) * 0.12) * step(0.45, sa);
let cola = mix(c3, c1, sa) * ba * 0.45;
let fb = vec2<f32>(p.x * 8.0, p.y * 8.0 - tt * 0.35);
let cb = floor(fb);
let sb = hash(cb + vec2<f32>(11.0, 5.0));
let lb = fract(fb) - 0.5 - (hash2(cb) - 0.5) * 0.3 + vec2<f32>(0.06 * sin(tt * 1.7 + sb * 6.28), 0.0);
let db = sd_circle(lb, (0.1 + 0.06 * sb) * bubble_size);
let bb = (stroke(db, 0.035) + fill(db) * 0.15) * step(0.4, sb);
let colb = mix(c1, c5, sb) * bb * 0.8;
let fc = vec2<f32>(p.x * 4.0, p.y * 4.0 - tt * 0.45);
let cc = floor(fc);
let sc = hash(cc + vec2<f32>(17.0, 9.0));
let lc = fract(fc) - 0.5 - (hash2(cc) - 0.5) * 0.3 + vec2<f32>(0.05 * sin(tt * 1.1 + sc * 6.28), 0.0);
let dc = sd_circle(lc, (0.1 + 0.06 * sc) * bubble_size);
let bc = (stroke(dc, 0.03) + fill(dc) * 0.1 + halo(dc, 0.05) * 0.3) * step(0.4, sc);
let colc = mix(c3, c5, sc) * bc * 1.2;
let col = surfc + glint + band2 + band3 + caustic + cola + colb + colc;
return mix(bg, tonemap(col * 1.2), strength);

let wave_a = 0.28 + 0.03 * sin(p.x * 4.0 + t * 0.5);
let wave_b = 0.02 + 0.04 * sin(p.x * 3.0 - t * 0.35 + 1.3);
let wave_c = -0.24 + 0.05 * sin(p.x * 2.2 + t * 0.25 + 2.0);
let edge_a = smoothstep(-0.02, 0.02, p.y - wave_a);
let edge_b = smoothstep(-0.02, 0.02, p.y - wave_b);
let edge_c = smoothstep(-0.02, 0.02, p.y - wave_c);
let deep = mix(c4 * 0.5, c4 * 0.9, clamp(p.y + 0.5, 0.0, 1.0));
let body = mix(deep, c1 * 0.45, edge_c);
let body2 = mix(body, c1 * 0.7, edge_b);
let water = mix(body2, c2 * 0.5, edge_a);
let crest = stroke(abs(p.y - wave_a), 0.015) * 0.5 + stroke(abs(p.y - wave_b), 0.012) * 0.35;
let rays = pow(abs(sin(p.x * 5.0 + sin(t * 0.3) * 2.0 + p.y)), 14.0) * smoothstep(-0.2, 0.4, p.y) * 0.15;
let g1 = p * 5.0 + vec2<f32>(0.0, -t * 0.35);
let cell1 = floor(g1);
let on1 = step(1.0 - 0.5 * bubble_density, hash(cell1));
let r1 = 0.12 + 0.06 * hash(cell1 + vec2<f32>(3.1, 7.7));
let d1 = sd_circle(fract(g1) - 0.5 - (hash2(cell1) - 0.5) * 0.5, r1);
let b1 = (stroke(d1, 0.025) * 0.9 + fill(d1) * 0.12) * on1;
let g2 = p * 10.0 + vec2<f32>(0.0, -t * 0.22);
let cell2 = floor(g2);
let on2 = step(1.0 - 0.5 * bubble_density, hash(cell2 + vec2<f32>(11.0, 2.0)));
let r2 = 0.10 + 0.05 * hash(cell2 + vec2<f32>(5.3, 1.9));
let d2 = sd_circle(fract(g2) - 0.5 - (hash2(cell2) - 0.5) * 0.5, r2);
let b2 = (stroke(d2, 0.03) * 0.7 + fill(d2) * 0.1) * on2;
let g3 = p * 18.0 + vec2<f32>(0.0, -t * 0.12);
let cell3 = floor(g3);
let on3 = step(1.0 - 0.5 * bubble_density, hash(cell3 + vec2<f32>(4.0, 9.0)));
let r3 = 0.08 + 0.04 * hash(cell3 + vec2<f32>(8.2, 3.3));
let d3 = sd_circle(fract(g3) - 0.5 - (hash2(cell3) - 0.5) * 0.5, r3);
let b3 = (stroke(d3, 0.04) * 0.5 + fill(d3) * 0.08) * on3;
let scene = water + c3 * crest + c3 * rays + c3 * b1 * 0.5 + c3 * b2 * 0.35 + c2 * b3 * 0.3;
return mix(bg, tonemap(scene), strength);

let row = floor(p.y * 60.0);
let gate = floor(t * 8.0);
let gh = hash(vec2<f32>(row, gate));
let g = step(0.94, gh) * glitch_amount;
let go = (hash(vec2<f32>(row + 3.0, gate)) - 0.5) * 0.18 * g;
let xs = p.x + go;
let u = fract(xs * 2.0 + t * beat_rate);
let a = (u - 0.5) / 0.03;
let qrs = 0.32 * exp(-a * a);
let b = (u - 0.72) / 0.06;
let tw = 0.07 * exp(-b * b);
let pk = (u - 0.36) / 0.04;
let pw = 0.05 * exp(-pk * pk);
let jitter = 0.01 * (hash(vec2<f32>(floor(xs * 300.0), gate)) - 0.5);
let trace_y = qrs + tw + pw + jitter;
let dist = abs(p.y - trace_y);
let core = stroke(dist, 0.006);
let glow = halo(dist, 0.05);
let gx = abs(fract(p.x * 10.0 + 0.5) - 0.5) / 10.0;
let gy = abs(fract(p.y * 10.0 + 0.5) - 0.5) / 10.0;
let gridl = 1.0 - smoothstep(0.0, 0.0025, min(gx, gy));
let grid_col = c2 * 0.35 * gridl;
let trace_col = c1 * (core + glow * 0.5);
let hot = c3 * core * smoothstep(0.1, 0.3, qrs) * 0.7;
let tear = c3 * g * 0.12;
let color = bg + grid_col + trace_col + hot + tear;
return mix(bg, color, strength);

let q = p * density;
let r = vec2<f32>(1.0, 1.7320508);
let h = r * 0.5;
let ga = (fract(q / r) - 0.5) * r;
let gb = (fract((q - h) / r) - 0.5) * r;
let gv = select(gb, ga, length(ga) < length(gb));
let cell = q - gv;
let e = abs(gv);
let hd = max(dot(e, vec2<f32>(0.5, 0.8660254)), e.x);
let edge = max(0.5 - hd, 0.0);
let idh = hash(cell);
let on = step(0.45, idh);
let lane = hash(vec2<f32>(floor(cell.y * 0.5), 7.0)) * 3.0;
let front = fract(cell.x * 0.12 - t * pulse_speed + lane);
let pk = exp(-front * 12.0) * on;
let body = mix(c4, c2 * 0.25, idh * 0.6) * (0.6 + 0.4 * on);
let edge_col = mix(c1, c2, hash(cell + vec2<f32>(3.1, 7.7)));
let line_glow = exp(-edge * 60.0) + exp(-edge * 12.0) * 0.3 * glow_amount;
let packet = c5 * pk * 1.4 + c1 * pk * 0.4 * (0.5 + idh);
let color = body + edge_col * line_glow * (0.5 + 0.5 * on) + packet;
return mix(bg, tonemap(color), strength);

let drift_t = t * drift;
let sun_p = vec2<f32>(0.25, 0.2);
let sun_d = length(p - sun_p);
let sun = fill(sun_d - 0.085);
let glow = halo(sun_d - 0.085, 0.4);
let n1 = noise(vec2<f32>(p.x * 2.5 + drift_t * 0.04, 1.0));
let n2 = noise(vec2<f32>(p.x * 3.5 - drift_t * 0.06, 5.0));
let n3 = noise(vec2<f32>(p.x * 2.0 + drift_t * 0.03, 9.0));
let h1 = -0.14 + 0.07 * sin(p.x * 3.0 + drift_t * 0.12) + 0.05 * (n1 - 0.5);
let h2 = -0.03 + 0.06 * sin(p.x * 4.5 - drift_t * 0.09 + 1.3) + 0.05 * (n2 - 0.5);
let h3 = 0.07 + 0.05 * sin(p.x * 6.0 + drift_t * 0.07 + 2.6) + 0.04 * (n3 - 0.5);
let haze_col = mix(c5, c1, 0.4);
let sky = mix(c4 * 0.6, c2 * 0.55, smoothstep(-0.5, 0.5, p.y)) + haze_col * (glow * 0.45 + sun * 0.7);
var scene = sky + c5 * sun;
scene = mix(scene, mix(c3 * 0.85, haze_col, 0.35), fill(p.y - h3));
scene = mix(scene, c2 * 0.95, fill(p.y - h2));
scene = mix(scene, c4 * 0.8, fill(p.y - h1));
let crest = stroke(p.y - h2, 0.008) * c1 * 0.8 + stroke(p.y - h1, 0.006) * c1 * 0.5;
let color = tonemap(scene + crest);
return mix(bg, color, strength);

let tt = t * drift;
let wash = mix(c4 * 0.6, c4 * 1.6, smoothstep(-0.5, 0.5, p.y));
let ga = vec2<f32>(p.x * 6.0 + tt * 0.03, p.y * 6.0 - tt * 0.05);
let ca = floor(ga);
let fa = fract(ga) - 0.5;
let sa = hash(ca);
let qa = rotate(fa, sa * 6.28318);
let da = max(max(abs(qa.x), abs(qa.x * 0.5 + qa.y * 0.866)), abs(qa.x * 0.5 - qa.y * 0.866)) - 0.24;
let la = fill(da) * step(0.55, sa);
let gb = vec2<f32>(p.x * 4.0 - tt * 0.02, p.y * 4.0 - tt * 0.12);
let cb = floor(gb);
let fb = fract(gb) - 0.5;
let sb = hash(cb + vec2<f32>(3.0, 5.0));
let qb = rotate(fb, sb * 6.28318);
let db = max(max(abs(qb.x), abs(qb.x * 0.5 + qb.y * 0.866)), abs(qb.x * 0.5 - qb.y * 0.866)) - 0.3;
let lb = fill(db) * step(0.5, sb);
let rb = stroke(db, 0.02) * step(0.5, sb);
let gc = vec2<f32>(p.x * 2.2 + tt * 0.01, p.y * 2.2 - tt * 0.3);
let cc = floor(gc);
let fc = fract(gc) - 0.5;
let sc = hash(cc + vec2<f32>(11.0, 2.0));
let qc = rotate(fc, sc * 6.28318 + tt * 0.2);
let dc = max(max(abs(qc.x), abs(qc.x * 0.5 + qc.y * 0.866)), abs(qc.x * 0.5 - qc.y * 0.866)) - 0.36;
let lc = fill(dc) * step(0.6, sc);
let rc = stroke(dc, 0.015) * step(0.6, sc);
let gs = fract((p.x + p.y) * 3.0 - tt * 0.15);
let stripe = smoothstep(0.0, 0.05, gs) * (1.0 - smoothstep(0.12, 0.18, gs));
let scene = wash + c2 * stripe * 0.25 + c1 * la * 0.35 + c1 * lb * 0.5 + c1 * rb * 0.4 + c1 * lc * 0.8 + c3 * rc * 0.6;
return mix(bg, tonemap(scene), strength);

let fog_a = noise(p * 2.5 + vec2<f32>(t * 0.03, 0.0));
let fog_b = noise(p * 2.5 + vec2<f32>(fog_a * 1.8, fog_a * 1.2 - t * 0.02));
let base = mix(bg, c3 * 0.35, fog_b);
var glow = vec3<f32>(0.0, 0.0, 0.0);
for (var i = 0; i < 64; i++) {
    let k = f32(i);
    let h = hash(vec2<f32>(k, 3.7));
    let x = fract(h * 91.3) * 1.7 - 0.85 + 0.06 * sin(t * 0.4 + h * 6.28);
    let y = fract(h * 37.1 - t * (0.015 + 0.02 * h)) - 0.5;
    let pos = vec2<f32>(x, y);
    let dist = length(p - pos);
    let pulse = 0.5 + 0.5 * sin(t * (1.5 + 2.0 * h) + h * 40.0);
    let tint = mix(c1, c2, step(0.5, h));
    glow += tint * exp(-dist * dist * 1400.0) * pulse;
    glow += tint * exp(-dist * dist * 120.0) * pulse * 0.15;
}
let night = tonemap(base + glow * 1.4);
return mix(bg, night, strength);

let r = length(p);
let warp = 0.6 * sin(p.x * 9.0 + t * 0.4) + 0.4 * sin(p.y * 13.0 - t * 0.3);
let rings = 0.5 + 0.5 * sin(r * 46.0 * ripple_scale - t * 2.2 + warp * 2.0);
let fade = exp(-r * 2.2);
let water = mix(c4, c3, 0.3 + 0.3 * sin(p.y * 3.0 + t * 0.2 + warp));
let ripple_light = mix(c3, c5, rings) * rings * rings * fade * 0.9;
var koi_col = vec3<f32>(0.0, 0.0, 0.0);
for (var i = 0; i < 8; i++) {
    let k = f32(i);
    let seed = hash(vec2<f32>(k, 3.0));
    let ang = t * koi_speed * (0.6 + 0.4 * seed) + k * 0.785;
    let ax = 0.45 + 0.25 * seed;
    let ay = 0.25 + 0.12 * fract(seed * 7.0);
    let pos = vec2<f32>(ax * cos(ang), ay * sin(2.0 * ang));
    let vel = vec2<f32>(-ax * sin(ang), 2.0 * ay * cos(2.0 * ang));
    let heading = atan2(vel.y, vel.x);
    let local = rotate(p - pos, -heading);
    let wiggle = 0.015 * sin(local.x * 40.0 - t * 6.0 * koi_speed);
    let lp = vec2<f32>(local.x, local.y - wiggle);
    let shape = length(lp / vec2<f32>(0.07 * koi_size, 0.022 * koi_size)) - 1.0;
    let d = shape * 0.022 * koi_size;
    let tint = mix(c1, c2, step(0.5, seed));
    let body = 1.0 - smoothstep(-0.004, 0.004, d);
    let aura = halo(d, 0.06) * 0.8;
    koi_col += tint * (body * 1.2 + aura);
}
let color = tonemap(water + ripple_light + koi_col);
return mix(bg, color, strength);

let sky = mix(c2, c1, smoothstep(-0.5, 0.5, p.y));
let wave = 0.5 + 0.5 * sin(p.x * 5.0 + t * 0.25 + sin(p.y * 9.0 - t * 0.3) * 1.2);
let wash = mix(sky, c3, wave * 0.35);
let seabed = fill(p.y + 0.4 - 0.02 * sin(p.x * 12.0 + t * 0.2));
let g = p.x * 3.0;
let cell = floor(g);
let seed = hash(vec2<f32>(cell, 3.0));
let q = polar(vec2<f32>((fract(g) - 0.5) / 3.0, p.y + 0.5));
let bend = sin(q.x * 14.0 + seed * 6.28 + t * 0.4) * 0.6;
let lobes = pow(abs(cos((q.y * 6.28318 + bend * 0.4) * (2.0 + floor(seed * 3.0)))), 2.0);
let d = q.x - (0.04 + 0.12 * lobes);
let coral = mix(c5, c3, seed);
let reef = mix(coral * 0.7, coral, fill(d)) + c2 * halo(d, 0.02) * 0.4;
let color = mix(wash, c4 * 1.4, seabed);
let scene = mix(color, reef, fill(d));
return mix(bg, tonemap(scene), strength);

let warp = 0.35 * sin(p.x * 3.0 + t * 0.15) * cos(p.y * 2.0 - t * 0.1);
let x = p.x * 2.5 * dune_scale + warp;
let dune = 0.5 * sin(x * 2.0 + t * 0.2) + 0.3 * sin(x * 3.7 - p.y * 1.5 + 1.3) + 0.2 * sin(x * 6.1 + sin(p.y * 4.0 + t * 0.3));
let surface = -0.08 + 0.12 * dune;
let mask = 1.0 - smoothstep(-0.01, 0.01, p.y - surface);
let caus = pow(abs(ridged(vec2<f32>(p.x * 4.0 + sin(t * 0.2) * 0.5, p.y * 4.0 + t * 0.08))), 3.0);
let caus2 = pow(abs(ridged(vec2<f32>(p.x * 6.0 - t * 0.05, p.y * 6.0 - t * 0.11 + 3.0))), 3.0);
let cau = (caus + caus2 * 0.6) * caustic_amount;
let water = mix(c5, c3 * 0.6, smoothstep(-0.5, 0.5, p.y));
let water_lit = water + c2 * smoothstep(0.1, 0.5, p.y) * 0.25 + c4 * cau * 0.6;
let sand_tone = mix(c1 * 0.45, c1, clamp(0.55 + 0.45 * dune, 0.0, 1.0));
let ripple = 0.5 + 0.5 * sin(x * 14.0 + dune * 3.0);
let sand_lit = sand_tone * (0.85 + 0.15 * ripple) + c4 * cau * 0.35;
let color = mix(water_lit, sand_lit, mask);
return mix(bg, tonemap(color * 1.2), strength);

let fp = p * smoke_scale;
let warp = vec2<f32>(fbm(fp + vec2<f32>(t * 0.03, 0.0)), fbm(fp + vec2<f32>(4.1, 1.7) - vec2<f32>(0.0, t * 0.025)));
let smoke = fbm(fp + 1.8 * warp + vec2<f32>(0.0, t * 0.04));
let drift = clamp(0.5 + 0.5 * (p.y * 1.4 + 0.6 * warp.x - 0.3), 0.0, 1.0);
let hue = mix(c1, c2, drift);
let ink = mix(c4 * 0.8, hue, smoothstep(0.35, 0.75, smoke));
let ph1 = fract(t * 0.06 * drop_speed);
let ph2 = fract(t * 0.05 * drop_speed + 0.37);
let ph3 = fract(t * 0.07 * drop_speed + 0.71);
let r1 = stroke(sd_circle(p - vec2<f32>(-0.32, 0.1), ph1 * 0.8), 0.004 + 0.01 * (1.0 - ph1)) * (1.0 - ph1);
