let far_l = fill(df) * (0.3 + 0.4 * sf) * (0.7 + 0.3 * sin(t * 0.5 + sf * 6.28));
let gm = p * 5.0 + vec2<f32>(mid_v * 0.8, drift * 0.1);
let sm = hash(floor(gm) + vec2<f32>(3.0, 1.0));
let dm = sd_circle(fract(gm) - 0.5, dot_size * (0.8 + 0.4 * sm));
let mid_l = fill(dm) * 0.6;
let gn = p * 2.6 + vec2<f32>(near_v, 0.0);
let sn = hash(floor(gn) + vec2<f32>(7.0, 5.0));
let dn = sd_circle(fract(gn) - 0.5, dot_size * 2.0 * (0.5 + sn));
let near_l = halo(dn, 0.08) * 0.5 + fill(dn) * 0.3;
let color = base + far_l * c5 * 0.5 + mid_l * c2 * 0.7 + near_l * mix(c1, c3, sn) * 0.6;
return mix(bg, tonemap(color), strength);

let g = p * scale_size;
let row = floor(g.y);
let gx = g.x + fract(row * 0.5);
let cell = vec2<f32>(floor(gx), row);
let lp = vec2<f32>(fract(gx) - 0.5, fract(g.y) - 0.5);
let dome = sd_circle(lp - vec2<f32>(0.0, 0.2), 0.5);
let body = fill(dome);
let rim = stroke(dome, 0.06);
let seed = hash(cell);
let wave = 0.5 + 0.5 * sin(p.x * 6.0 + p.y * 2.0 - t * ripple_speed);
let wave2 = 0.5 + 0.5 * sin(p.x * 13.0 - p.y * 4.0 + t * ripple_speed * 0.6 + seed * 1.5);
let sheen = pow(wave * wave2, 3.0);
let base = mix(c2, c1, seed);
let shade = mix(base * 0.45, base, smoothstep(-0.5, 0.5, lp.y));
let pearl = c5 * sheen * rim;
let scale_col = shade * (0.6 + 0.6 * wave) * body;
let water = mix(c4, c2 * 0.5, wave * 0.6);
let colr = mix(water, scale_col + pearl * 1.2, body + rim * 0.6);
