return mix(bg, tonemap(out_col * 1.2), strength);

let base = mix(c3 * 0.25, c5 * 0.5, smoothstep(-0.5, 0.5, p.y));
let col_g = p.x * 9.0;
let col = floor(col_g);
let colseed = hash(vec2<f32>(col, 3.0));
let fall = (0.1 + 0.12 * colseed) * fall_speed;
let g = vec2<f32>(col_g, p.y * 6.0 + t * fall + colseed * 7.0);
let cell = floor(g);
let seed = hash(cell);
let jitter = (hash2(cell) - 0.5) * 0.3;
let sway = vec2<f32>(0.08 * sin(t * 0.5 + colseed * 6.28), 0.0);
let local = fract(g) - 0.5 - jitter - sway;
let arms = abs(local.x) + abs(local.y);
let size = (0.1 + 0.08 * seed) * flake_size;
let diamond = arms - size;
let cross_d = max(min(abs(local.x), abs(local.y)) - 0.012, arms - size * 1.5);
let lit = step(0.35, seed);
let twinkle = 0.65 + 0.35 * sin(t * (0.6 + seed) + seed * 9.0);
let rim = stroke(diamond, 0.018);
let core = fill(diamond + size * 0.5);
let spark = fill(cross_d);
let flakes = (mix(c1, c2, core) * max(rim, spark * 0.7) + c1 * halo(diamond, 0.05) * 0.3) * lit * twinkle;
let color = base + flakes * 1.2;
return mix(bg, tonemap(color), strength);

let pw = p + vec2<f32>(0.012 * sin(p.y * 9.0 + t * 0.8), 0.0);
let column = floor(pw.x * 7.0);
let pace = hash(vec2<f32>(column, 3.0));
let g = vec2<f32>(pw.x * 7.0, pw.y * 5.0 + t * slide_speed * (0.6 + pace) + pace * 7.0);
let cell = floor(g);
let seed = hash(cell);
let local = fract(g) - 0.5;
let jitter = vec2<f32>((hash(cell + vec2<f32>(5.0, 1.0)) - 0.5) * 0.4, 0.0);
let wob = sin(t * 4.0 + seed * 6.28) * wobble;
let stretch = 1.0 + 0.18 * sin(t * 6.0 + seed * 9.0);
let q = (local - jitter - vec2<f32>(wob, 0.0)) * vec2<f32>(1.0, stretch);
let spawn = step(0.3, seed);
let body = sd_circle(q, drop_size);
let trail = sd_segment(q, vec2<f32>(0.0, 0.0), vec2<f32>(0.0, 0.22)) - drop_size * 0.5;
let trail_mask = fill(trail) * (1.0 - smoothstep(0.0, 0.22, q.y)) * step(0.0, q.y) * 0.6;
let drop_fill = fill(body);
let rim = stroke(body, 0.02);
let shine = fill(sd_circle(q - vec2<f32>(-drop_size * 0.35, drop_size * 0.35), drop_size * 0.28));
let tint = mix(c1, c3, hash(cell + vec2<f32>(7.0, 3.0)));
let droplet = mix(tint * 0.6, tint, drop_fill) + c5 * rim * 0.8 + c5 * shine * 0.9;
let sky = mix(c4 * 1.3, c2 * 0.45, smoothstep(-0.5, 0.5, p.y));
let glow = c1 * halo(body, 0.05) * 0.4;
let color = sky + spawn * (droplet * drop_fill + c1 * trail_mask * 0.9 + glow);
return mix(bg, tonemap(color), strength);

let col = floor(p.x * 14.0);
let pace = 0.5 + hash(vec2<f32>(col, 3.0));
let g = vec2<f32>(p.x * 14.0, p.y * 9.0 + t * rain_speed * pace * 0.5 + hash(vec2<f32>(col, 7.0)) * 10.0);
let cell = floor(g);
let q = fract(g) - 0.5;
let on = step(0.45, hash(cell));
let off = (hash2(cell) - 0.5) * vec2<f32>(0.3, 0.2);
let local = q - off;
let d = sd_segment(local, vec2<f32>(-0.09, 0.16), vec2<f32>(0.09, -0.16));
let line = (1.0 - smoothstep(0.012, 0.028, d)) * on;
let tone = select(c1, c2, hash(cell + vec2<f32>(11.0, 5.0)) > 0.8);
let ink = mix(bg, tone, line * 0.9);
return mix(bg, ink, strength);

let beat_x = p.x * 1.6 + t * 0.5;
let u = fract(beat_x);
let a1 = (u - 0.18) / 0.04;
let pw = 0.12 * exp(-a1 * a1);
let a2 = (u - 0.36) / 0.012;
let qw = -0.10 * exp(-a2 * a2);
let a3 = (u - 0.40) / 0.012;
let rw = 1.0 * exp(-a3 * a3);
let a4 = (u - 0.44) / 0.014;
let sw = -0.25 * exp(-a4 * a4);
let a5 = (u - 0.62) / 0.06;
let tw = 0.22 * exp(-a5 * a5);
let wave = pw + qw + rw + sw + tw;
let trace_y = 0.06 + wave * 0.2;
let dist = abs(p.y - trace_y);
let core = 1.0 - smoothstep(0.002, 0.007, dist);
let halo_t = exp(-dist * dist * 180.0);
