let fc = fract(xcol);
let cold = min(fc, 1.0 - fc);
let cols = 1.0 - smoothstep(0.0, 0.05, cold);
let grid_c = c2 * max(rows, cols) * ground * 0.8;
let sky = mix(c4, c3 * 0.5, smoothstep(0.0, 0.5, p.y));
let sd = sd_circle(p - vec2<f32>(0.0, 0.1), 0.2);
let sun_mask = fill(sd);
let stripes = smoothstep(0.35, 0.6, fract(p.y * 22.0 - t * 0.08));
let sun_st = sun_mask * mix(1.0, stripes, 1.0 - smoothstep(0.0, 0.12, p.y));
