let color = tonemap(lit * scan);
return mix(bg, color, strength);

let q = vec2<f32>(fbm(p * 2.0 + vec2<f32>(t * 0.02, 0.0)), fbm(p * 2.0 + vec2<f32>(5.2, 1.3) - vec2<f32>(0.0, t * 0.015)));
