let q = p * vec2<f32>(2.2, 1.4) + vec2<f32>(0.0, -t * 0.06);
let w = vec2<f32>(fbm(q + vec2<f32>(1.7, 9.2)), fbm(q + vec2<f32>(8.3, 2.8) + vec2<f32>(0.0, t * 0.03)));
