let haze = mix(wash, c3, swirl * 0.35);
let ink = mix(haze, c1, ink_disk * 0.92);
let color = ink + c5 * rim * 0.5;
return mix(bg, color, strength);

let w = vec2<f32>(fbm(p * 1.6 + vec2<f32>(t * 0.02, 0.0)), fbm(p * 1.6 + vec2<f32>(5.2, 1.3) - vec2<f32>(0.0, t * 0.015)));
let q = p * (vein_scale * 2.5) + 1.6 * (w - 0.5);
