let color = mix(surface, gold, vein * 0.85) + c3 * glint * 0.6 + c5 * glint * glint * 0.3;
return mix(bg, tonemap(color * 1.25), strength);

let q = polar(p);
let rA = 64.0;
let fA = q.y * rA;
let idA = floor(fA);
let sA = hash(vec2<f32>(idA, 3.0));
let wA = (noise(vec2<f32>(q.x * 5.0 - t * 0.4, idA * 0.37)) - 0.5) * 0.7;
