let lenA = 0.05 + 0.55 * hA;
let tailA = smoothstep(headA - lenA, headA, q.x) * step(q.x, headA);
let lineA = 1.0 - smoothstep(0.002, 0.006 + 0.004 * sA, aA);
let glowA = 1.0 - smoothstep(0.0, 0.025, abs(q.x - headA));
let nearA = smoothstep(0.02, 0.12, q.x);
let streakA = mix(c2, c3, glowA) * tailA * lineA * nearA;

