let fB = q.y * rB + 0.5;
let idB = floor(fB);
let sB = hash(vec2<f32>(idB, 11.0));
let wB = (noise(vec2<f32>(q.x * 8.0 - t * 0.3, idB * 0.61)) - 0.5) * 0.9;
let aB = abs(fract(fB + wB) - 0.5) * 6.2831853 / rB * q.x;
let hB = fract(sB + t * (0.03 + 0.05 * sB));
let headB = 0.03 + hB * hB * 1.2;
let lenB = 0.03 + 0.35 * hB;
let tailB = smoothstep(headB - lenB, headB, q.x) * step(q.x, headB);
let lineB = 1.0 - smoothstep(0.001, 0.004, aB);
let nearB = smoothstep(0.03, 0.15, q.x);
