let wash = mix(c1 * 0.35, c4 * 0.3, smoothstep(-0.5, 0.5, p.y));
let core = c5 * halo(sd_circle(p, 0.02), 0.08) * 0.9;
let vignette = clamp(1.0 - 0.7 * dot(p, p), 0.0, 1.0);
let color = (wash + streakA + streakB + core) * vignette;
