let sky = mix(c4, c2 * 0.6, smoothstep(-0.5, 0.5, p.y));
let sun_d = sd_circle(p - vec2<f32>(0.3, 0.2), 0.12);
var scene = mix(sky, c3, fill(sun_d));
scene = mix(scene, c4, stroke(sun_d, 0.008));
for (var i = 0; i < 4; i++) {
    let k = f32(i);
    let base = 0.1 - 0.15 * k;
    let freq = 2.5 + 1.2 * k;
    let spd = wave_speed * (0.5 + 0.3 * k);
    let edge = base + wave_height * 0.05 * sin(p.x * freq + t * spd + k * 2.1) + wave_height * 0.02 * sin(p.x * freq * 2.7 - t * spd * 1.3);
