let ga = p * 3.0 * glyph_size + vec2<f32>(t * 0.06, t * 0.02);
let ca = floor(ga);
let fa = fract(ga) - 0.5;
let ha = hash(ca);
let ra = rotate(fa, t * (0.2 + 0.3 * ha) + ha * 6.28);
let ka = 1.0 + 0.45 * sin(t * 0.9 + ha * 6.28);
let ring = stroke(sd_circle(vec2<f32>(ra.x / ka, ra.y * ka), 0.16), 0.012);
let bond = vec2<f32>(0.14 * cos(t * 0.5 + ha * 9.0), 0.14 * sin(t * 0.5 + ha * 9.0));
let mol = min(min(sd_circle(ra - vec2<f32>(-0.12, 0.0), 0.03), sd_circle(ra - bond, 0.03)), sd_segment(ra, vec2<f32>(-0.12, 0.0), bond));
let far = stroke(mol, 0.01) * 0.5 + ring * 0.35;
let gb = p * 1.6 * glyph_size - vec2<f32>(t * 0.12, 0.0);
let cb = floor(gb);
let fb = fract(gb) - 0.5;
let hb = hash(cb + vec2<f32>(3.0, 7.0));
let rb = rotate(fb, sin(t * 0.7 + hb * 6.28) * 0.8);
let corner = min(sd_segment(rb, vec2<f32>(0.0, -0.18), vec2<f32>(0.0, 0.18)), sd_segment(rb, vec2<f32>(0.0, -0.18), vec2<f32>(0.18, -0.18)));
let dotb = sd_circle(rb - vec2<f32>(0.24, 0.18), 0.025);
