let g1 = p * 4.0 * density + vec2<f32>(t * 0.03, 0.0);
let k1 = floor(g1);
let f1 = fract(g1) - 0.5;
let s1 = hash(k1);
let r1 = rotate(f1, t * spin_speed * (0.15 + 0.3 * s1));
let w1 = 0.5 + 0.5 * sin(t * 0.7 + s1 * 6.28);
let reach1 = 0.14 + 0.06 * morph_amount * w1;
let mol1 = min(sd_circle(r1 - vec2<f32>(-reach1, 0.0), 0.035), sd_circle(r1 - vec2<f32>(reach1, 0.0), 0.035));
let bond1 = stroke(sd_segment(r1, vec2<f32>(-reach1, 0.0), vec2<f32>(reach1, 0.0)), 0.01);
let ov1 = vec2<f32>(r1.x, r1.y * (1.0 + morph_amount * w1));
