let layer_far = (c5 * (fill(mol1) + halo(mol1, 0.05) * 0.4) + c1 * (bond1 + ring1) * 0.5) * 0.45;
let g2 = p * 2.2 * density + vec2<f32>(-t * 0.08, 0.0);
let k2 = floor(g2);
let f2 = fract(g2) - 0.5;
let s2 = hash(k2);
let r2 = rotate(f2, sin(t * 0.4 + s2 * 6.28) * 0.6 * spin_speed);
let corner = min(sd_segment(r2, vec2<f32>(0.3, 0.3), vec2<f32>(0.3, -0.3)), sd_segment(r2, vec2<f32>(0.3, -0.3), vec2<f32>(0.0, -0.3)));
let wave2 = abs(r2.y - 0.12 * cos(r2.x * 6.28318 + t * 1.5 + s2 * 6.28));
let layer_mid = c2 * stroke(corner, 0.012) * 0.7 + c4 * stroke(wave2, 0.01) * 0.6 + c4 * fill(sd_circle(r2 - vec2<f32>(-0.3, 0.25), 0.03));
let g3 = p * 1.2 * density + vec2<f32>(t * 0.15, t * 0.02);
let k3 = floor(g3);
let f3 = fract(g3) - 0.5;
let s3 = hash(k3);
let r3 = rotate(f3, t * 0.1 * spin_speed);
let orbit = vec2<f32>(cos(t * 0.5 + s3 * 6.28), sin(t * 0.5 + s3 * 6.28)) * 0.28;
let squash3 = 1.0 + morph_amount * 0.5 * sin(t * 0.6 + s3 * 6.28);
