let atom = sd_circle(r3 - orbit, 0.035);
let layer_near = c3 * ring3 * 0.6 + c1 * fill(atom) + c1 * halo(atom, 0.08) * 0.4;
let glow = layer_far + layer_mid * 0.9 + layer_near * 0.8;
let vign = clamp(1.0 - 0.6 * dot(p, p), 0.3, 1.0);
