return mix(bg, tint, strength);

let sky = mix(c4 * 0.45, c4 * 0.2, step(0.0, p.y + 0.08 * sin(p.x * 4.0 + t * 0.4 * speed)));
let g1 = rotate(p, 0.2 * sin(t * 0.07 * speed)) * density * 0.5 + vec2<f32>(t * 0.05 * speed, 0.0);
let k1 = floor(g1);
let s1 = hash(k1);
let l1 = fract(g1) - 0.5;
let m1 = 0.5 + 0.5 * sin(t * speed * 0.6 + s1 * 6.28);
let a1 = sd_circle(l1 * vec2<f32>(1.0, 1.0 + 0.6 * m1), 0.26);
let b1 = sd_box(rotate(l1, t * 0.4 * speed + s1 * 6.28), vec2<f32>(0.2, 0.2));
let w1 = abs(l1.y - 0.18 * cos(l1.x * 10.0 + t * 2.0 * speed + s1 * 6.28)) - 0.03;
let o1 = sd_circle(l1, 0.09 + 0.04 * sin(t * 2.0 * speed + s1));
let d1 = select(select(w1, o1, s1 < 0.75), mix(a1, b1, m1), s1 < 0.5);
let col1 = mix(mix(c1, c2, step(0.33, s1)), c5, step(0.66, s1));
let L1 = mix(sky, col1 * 0.55, fill(d1));
let P1 = mix(L1, bg, stroke(d1, outline_w * 0.6));
let g2 = rotate(p, -0.3 * sin(t * 0.09 * speed)) * density * 0.8 + vec2<f32>(0.0, t * 0.08 * speed);
let k2 = floor(g2);
let s2 = hash(k2 + vec2<f32>(13.0, 5.0));
let l2 = fract(g2) - 0.5;
let m2 = 0.5 + 0.5 * sin(t * speed * 0.8 + s2 * 6.28);
let a2 = sd_circle(l2 * vec2<f32>(1.0 + 0.5 * m2, 1.0), 0.22);
let b2 = sd_box(rotate(l2, t * 0.6 * speed + s2 * 6.28), vec2<f32>(0.18, 0.18));
let w2 = abs(l2.x - 0.16 * cos(l2.y * 10.0 + t * 2.4 * speed + s2 * 6.28)) - 0.03;
let o2 = sd_circle(l2, 0.08 + 0.03 * sin(t * 2.5 * speed + s2));
let d2 = select(select(w2, o2, s2 < 0.75), mix(a2, b2, m2), s2 < 0.5);
let col2 = mix(c3, c2, step(0.5, s2));
let L2 = mix(P1, col2 * 0.8, fill(d2));
let P2 = mix(L2, bg, stroke(d2, outline_w * 0.8));
let g3 = p * density * 1.2 + vec2<f32>(t * 0.25 * speed, sin(t * 0.3 * speed) * 0.1);
let k3 = floor(g3);
let s3 = hash(k3 + vec2<f32>(29.0, 11.0));
let l3 = fract(g3) - 0.5;
let m3 = 0.5 + 0.5 * sin(t * speed * 1.1 + s3 * 6.28);
let a3 = sd_circle(l3 * vec2<f32>(1.0, 1.0 + 0.7 * m3), 0.28);
let b3 = sd_box(rotate(l3, t * 0.8 * speed + s3 * 6.28), vec2<f32>(0.21, 0.21));
