let g1 = p * 4.0 + vec2<f32>(t * 0.08, t * 0.03);
let tile1 = floor(g1);
let s1 = hash(tile1);
let r1 = rotate(fract(g1) - 0.5, t * 0.35 + s1 * 6.2832);
let m1 = 0.5 + 0.5 * sin(t * 0.6 + s1 * 9.0);
let d1 = mix(sd_circle(r1 * vec2<f32>(1.5, 1.0), 0.13), sd_box(r1, vec2<f32>(0.11, 0.11)), m1);
let sh1 = stroke(d1, 0.012) * step(0.5, s1);
let g2 = p * 2.5 + vec2<f32>(t * 0.04, 0.0);
let tile2 = floor(g2);
let s2 = hash(tile2);
let r2 = rotate(fract(g2) - 0.5, t * 0.2 + s2 * 6.2832);
let corner = sd_segment(r2, vec2<f32>(0.0, -0.12), vec2<f32>(0.0, 0.12));
let arm = sd_segment(r2, vec2<f32>(0.0, -0.12), vec2<f32>(0.14, -0.12));
