let dot2 = halo(sd_circle(r2 - vec2<f32>(-0.18, 0.12), 0.02), 0.05);
let far = (ell + dot2) * step(0.55, s2);
let wave = 0.2 * cos(p.x * 7.0 + t * 0.6) + 0.05 * sin(p.x * 15.0 - t);
let wline = stroke(p.y - wave, 0.008) * (1.0 - smoothstep(0.2, 0.9, abs(p.x)));
let base = bg + c4 * 0.12 * smoothstep(-0.5, 0.5, p.y);
let color = base + mix(c1, c2, s1) * sh1 * 0.9 + c4 * far * 0.7 + c3 * wline * 0.8;
