    let dir = select(-1.0, 1.0, seed > 0.5);
    let r = rotate(fract(g) - 0.5, t * (0.2 + 0.5 * seed) * dir);
    let morph = 0.5 + 0.5 * sin(t * morph_rate * (0.8 + seed) + seed * 6.28);
