let band_d = abs(p.y + 0.28 - 0.05 * cos(p.x * 10.0 - t * 1.2)) - 0.004;
let band = (1.0 - smoothstep(0.0, 0.01, band_d)) * c5;
let haze = c4 * 0.12 * clamp(1.0 - length(p) * 1.4, 0.0, 1.0);
let lit = tonemap(col + band * 0.9 + haze);
return mix(bg, clamp(bg + lit, vec3<f32>(0.0), vec3<f32>(1.0)), strength);

let wash = mix(bg, c2 * 0.10, smoothstep(-0.5, 0.5, p.y));
var col = vec3<f32>(0.0, 0.0, 0.0);
for (var i = 0; i < 3; i++) {
    let k = f32(i);
    let spd = (0.03 + 0.05 * k) * drift_speed;
    let scale = 2.2 + 1.6 * k;
    let dim = 0.35 + 0.3 * k;
    let sz = (0.07 + 0.05 * k) * shape_size;
    let g = p * scale + vec2<f32>(t * spd, 0.15 * sin(t * 0.13 + k * 2.0));
    let cell = floor(g);
    let local = fract(g) - 0.5;
    let seed = hash(cell + vec2<f32>(k * 17.0, 3.0));
    let seed2 = hash(cell * 1.7 + vec2<f32>(9.0, k * 5.0));
    let dir = select(-1.0, 1.0, seed2 > 0.5);
    let spin = t * (0.2 + 0.5 * seed) * dir + seed * 6.28;
    let r = rotate(local, spin);
    let m = 0.5 + 0.5 * sin(t * 0.3 + seed * 6.28);
    let oval = length(r * vec2<f32>(1.0, 0.55 + 0.45 * m)) - sz;
    let box = sd_box(r, vec2<f32>(sz * 0.8, sz * 0.8)) - sz * 0.15;
    let morph_d = mix(oval, box, m);
    let wave_d = max(abs(r.y - 0.5 * sz * cos(r.x * 9.0 + t * 1.2 + seed * 6.28)) - 0.006, abs(r.x) - sz * 1.2);
    let dot_d = sd_circle(r, sz * 0.25);
    let corner = min(sd_segment(r, vec2<f32>(-sz, -sz), vec2<f32>(sz, -sz)), sd_segment(r, vec2<f32>(-sz, -sz), vec2<f32>(-sz, sz))) - 0.006;
    let pick = floor(seed2 * 4.0);
    var d = morph_d;
    if (pick >= 1.0 && pick < 2.0) {
        d = wave_d;
    }
    if (pick >= 2.0 && pick < 3.0) {
        d = corner;
    }
    if (pick >= 3.0) {
        d = dot_d;
    }
    let present = step(0.3, seed);
    let line = stroke(d, 0.008) + halo(d, 0.025) * 0.4;
    let hue = mix(c1, c2, seed2);
