return mix(bg, tonemap(color), strength);

let bgwash = mix(c4 * 0.45, c2 * 0.12, smoothstep(-0.5, 0.5, p.y));
var acc = vec3<f32>(0.0);
for (var i = 0; i < 3; i++) {
    let k = f32(i);
    let scale = 7.0 - k * 2.0;
    let speed = 0.05 + 0.08 * k;
    let g = p * scale + vec2<f32>(t * speed, 0.2 * sin(t * 0.3 + k));
    let cell = floor(g);
    let seed = hash(cell + vec2<f32>(k * 17.0, 3.0));
    let dir = select(-1.0, 1.0, seed > 0.5);
    let ang = seed * 6.28 + t * (0.3 + seed) * dir;
    let q = rotate(fract(g) - 0.5, ang);
    let morph = 0.5 + 0.5 * sin(t * morph_speed + seed * 12.0);
    let r = 0.12 + 0.07 * hash(cell * 1.7);
    let oval = length(q * vec2<f32>(1.0, 1.6 + 0.8 * morph)) - r;
    let corner = min(sd_segment(q, vec2<f32>(-r, -r), vec2<f32>(r, -r)), sd_segment(q, vec2<f32>(-r, -r), vec2<f32>(-r, r))) - 0.02;
    let dotline = min(sd_circle(q - vec2<f32>(-r * 1.2, 0.0), r * 0.35), sd_segment(q, vec2<f32>(-r * 0.6, 0.0), vec2<f32>(r * 1.4, 0.0)) - 0.02);
