    let dk = abs(p.y - yk);
    let tint = mix(mix(c2, c1, 0.5), c5, f32(i) * 0.2);
    tg += tint * (0.0002 / (dk * dk + 0.0002)) * 0.3;
}
let dc = abs(p.y - y);
let core = exp(-dc * dc * 250000.0);
let halo_w = 0.00025 / (dc * dc + 0.00025);
let spark = sin(p.x * 140.0 + t * 17.0) * sin(p.x * 53.0 - t * 11.0);
let sparks = spark * spark * halo_w * 1.5 * mix(c1, c3, 0.5);
let line = vec3<f32>(1.0, 0.97, 1.0) * core * 1.3 + sparks;
let haze = mix(c4 * 0.9, c2 * 0.35, smoothstep(-0.5, 0.5, p.y));
let grid = pow(abs(sin(p.x * 45.0) * sin(p.y * 45.0)), 8.0) * 0.25;
let scan = 0.9 + 0.1 * sin(p.y * 1200.0);
let col = (haze + grid * c2 * 0.5) * scan + line + tg * glow_amount + halo_w * c1 * 0.15;
let vignette = clamp(1.2 - 1.1 * dot(p, p), 0.0, 1.0);
return mix(bg, tonemap(col * 1.1) * vignette, strength);

let tt = t * wave_speed;
let grid = abs(fract(p * vec2<f32>(10.0, 6.0)) - 0.5);
let grid_line = smoothstep(0.46, 0.5, max(grid.x, grid.y));
let base = mix(bg, c4, smoothstep(-0.5, 0.5, p.y) * 0.8) + c2 * grid_line * 0.08;
var glow_col = vec3<f32>(0.0);
for (var i = 0; i < 4; i++) {
    let k = f32(i);
    let f = 1.0 + k * 0.6;
    let x = p.x * 3.14159 * f + tt * (0.6 + 0.3 * k);
    let amp = 0.16 - 0.025 * k;
    let fund = sin(x + k * 1.7);
    let h2 = sin(2.0 * x - tt * 0.9 + k) * harmonic_mix * 0.45;
    let h3 = sin(3.0 * x + tt * 0.4) * harmonic_mix * 0.2;
    let y = (fund + h2 + h3) * amp;
    let d = abs(p.y - y);
    let wave_line = 1.0 - smoothstep(0.0015, 0.0045, d);
    let bloom = exp(-d * 30.0) * 0.5;
    let tint = mix(mix(c1, c2, smoothstep(0.5, 1.5, k)), mix(c3, c5, smoothstep(2.5, 3.0, k)), smoothstep(1.5, 2.5, k));
    glow_col += tint * (wave_line + bloom);
}
return mix(bg, tonemap(base + glow_col * 1.3), strength);

let haze = cloud(p * 2.0 + vec2<f32>(t * 0.02, 0.0));
let hx = p.x * 0.5 + 0.5;
let pat = (0.5 + 0.5 * sin(p.x * 120.0) * sin(p.y * 90.0)) * 0.04;
let base = bg + mix(c4, c2 * 0.25, haze) * 0.5 * (0.6 + 0.4 * smoothstep(-0.5, 0.5, p.y)) + vec3<f32>(pat * 0.2, 0.0, pat);
var ya = 0.0;
var yb = 0.0;
for (var i = 1; i <= 5; i++) {
    let k = f32(i);
    let hw = select(harmonics, 1.0, i == 1);
    ya += hw * sin(p.x * 5.0 * k + t * wave_speed * (0.6 + 0.2 * k) + k * 1.3) / k;
    yb += hw * sin(p.x * 3.7 * k - t * wave_speed * (0.5 + 0.15 * k) + k * 2.1) / (k * 1.2);
}
let env = 1.0 - 0.3 * p.x * p.x;
let ca = p.y - ya * 0.07 * env;
let cb = p.y - (yb * 0.05 + 0.03 * sin(p.x * 2.0 + t * 0.4)) * env;
let da = abs(ca);
let db = abs(cb);
let coreA = 1.0 - smoothstep(0.0, 0.0028, da);
let coreB = (1.0 - smoothstep(0.0, 0.002, db)) * 0.7;
let glowA = exp(-da * 45.0) * glow_amount;
let glowB = exp(-db * 35.0) * glow_amount * 0.6;
let lineA = mix(mix(c2, c5, smoothstep(0.0, 0.5, hx)), c1, smoothstep(0.5, 1.0, hx));
let lineB = mix(c1, c3, smoothstep(0.0, 1.0, hx));
let sc = vec2<f32>(floor(p.x * 70.0), floor(t * 10.0));
let spark = step(0.985, hash(sc)) * exp(-da * 70.0);
let light = lineA * (coreA * 1.4 + glowA * 0.8) + lineB * (coreB + glowB) + vec3<f32>(1.0) * coreA * 0.6 + c5 * spark * 1.2;
let color = base + light;
return mix(bg, tonemap(color), strength);

var wave = 0.0;
var wave2 = 0.0;
var slope = 0.0;
for (var i = 0; i < 5; i++) {
    let k = f32(i);
    let freq = 1.0 + k;
    let amp = wave_gain * 0.12 / (1.0 + k);
    let ph = t * wave_speed * (1.0 + 0.35 * k);
