let dist2 = abs(p.y - wave2 - 0.02) / sqrt(1.0 + 4.0 * abs(sin(p.x * 9.0)));
let line = 1.0 - smoothstep(0.0015, 0.0042, dist);
let line2 = 1.0 - smoothstep(0.0012, 0.0032, dist2);
let glow = exp(-dist * 55.0) * 0.8 + exp(-dist * 16.0) * 0.22;
let glow2 = exp(-dist2 * 40.0) * 0.45;
let sparks = step(0.982, hash(vec2<f32>(floor(p.x * 45.0), floor(t * 7.0)))) * exp(-dist * 110.0);
let tint = mix(mix(c1, c2, smoothstep(-0.9, 0.0, p.x)), mix(c3, c5, smoothstep(0.0, 0.9, p.x)), smoothstep(-0.3, 0.6, p.x));
let haze = c4 * (0.5 + 0.5 * sin(p.x * 2.0 + p.y * 3.0 + t * 0.1)) * 0.6;
let g = abs(fract(p * 12.0) - 0.5);
let grid = (1.0 - smoothstep(0.42, 0.5, max(g.x, g.y))) * 0.07;
let base = bg + haze * 0.5 + c4 * grid;
