let scan = 0.5 + 0.5 * sin(p.y * 220.0);
let base = c4 * (0.7 + 0.3 * scan) * (1.2 - abs(p.x) * 0.4);
let total = base + glow;
return mix(bg, tonemap(total * 1.3), strength);

let wob = wobble * (0.6 * sin(t * 0.37 + p.x * 2.3) + 0.4 * sin(t * 0.91 - p.x * 5.1));
let hz = 0.04 + wob;
let floor_mask = 1.0 - step(hz, p.y);
let d = max(hz - p.y, 0.015);
let depth = 1.0 / d;
let gz = depth * 0.35 + t * speed;
let gx = p.x * depth * 0.5;
let hd = abs(fract(gz + 0.5) - 0.5);
let vd = abs(fract(gx + 0.5) - 0.5);
let hl = 1.0 - smoothstep(0.0, line_w, hd);
let vl = 1.0 - smoothstep(0.0, line_w * 0.8, vd);
let row = hash(vec2<f32>(floor(gz), 3.0));
let flick = 0.6 + 0.4 * sin(t * 2.0 + row * 6.28);
let vis = smoothstep(0.015, 0.4, d);
let grid = max(hl, vl * 0.9) * vis * flick;
let glow_line = smoothstep(0.5, 0.0, hd) * 0.2 * vis;
let floor_col = c2 * (grid * 1.2 + glow_line) + c3 * 0.15 * vis;
let horizon = c2 * 0.35 * exp(-abs(p.y - hz) * 18.0);
let mist = noise(vec2<f32>(p.x * 3.0 + t * 0.05, p.y * 4.0)) * exp(-abs(p.y - hz) * 6.0);
let sky = horizon + c3 * 0.25 * mist;
let scene = mix(sky, floor_col, floor_mask);
return mix(bg, tonemap(bg + scene), strength);

let depth = 0.75 - p.y;
let fl = vec2<f32>(p.x / depth, 1.0 / depth) * 0.9 + vec2<f32>(0.0, t * 0.15);
let cell = floor(fl);
let local = fract(fl) - 0.5;
let frame = max(abs(local.x), abs(local.y));
let tile_in = 1.0 - smoothstep(0.40, 0.42, frame);
let gold_rim = smoothstep(0.38, 0.41, frame) * (1.0 - smoothstep(0.44, 0.47, frame));
let beam_x = 0.8 * sin(t * 0.45) + 0.3 * p.y;
let dist_b = abs(p.x - beam_x);
let beam = exp(-(dist_b * dist_b) / (beam_width * (0.006 + 0.02 * depth)));
