let tint = hsv(hue, 0.55, 0.95);
let flash = clamp(beam * (0.7 + 0.3 * hash(cell)) * 1.5, 0.0, 1.0);
let tile = mix(c4 * 1.4, tint, 0.3 + 0.7 * flash) * tile_in;
let rim = mix(c1, c5, beam) * gold_rim * (0.5 + 0.8 * beam);
let beam_glow = c2 * beam * 0.3;
let fade = clamp(1.3 - depth * 0.6, 0.0, 1.0);
let color = tonemap((tile + rim + beam_glow) * fade);
return mix(bg, color, strength);

let hz = -0.03;
let below = max(hz - p.y, 0.015);
let depth = 1.0 / below;
let X = p.x * depth;
let Z = depth;
let tw = t * wave_speed;
let a1 = X * 1.3 + Z * 0.7 - tw * 1.1;
let a2 = X * 2.1 - Z * 1.1 + tw * 1.4;
let a3 = X * 0.6 + Z * 2.3 - tw * 0.8;
let a4 = X * 3.7 + Z * 3.1 + tw * 2.0;
let h = sin(a1) * 0.5 + sin(a2) * 0.3 + sin(a3) * 0.2 + sin(a4) * 0.12;
let gx = 0.65 * cos(a1) + 0.63 * cos(a2) + 0.12 * cos(a3) + 0.44 * cos(a4);
let gz = 0.35 * cos(a1) - 0.33 * cos(a2) + 0.46 * cos(a3) + 0.37 * cos(a4);
let slope = 0.2 * wave_height;
let fine = noise(vec2<f32>(X * 4.0 - tw * 0.6, Z * 2.0 + tw * 0.3));
let nx = (-gx) * slope + (fine - 0.5) * 0.075;
let nz = (-gz) * slope;
let n = normalize(vec3<f32>(nx, 1.0, nz));
let refl_mix = clamp(0.3 + 4.0 * (1.0 - n.y), 0.0, 1.0);
let fog = exp(-below * 2.5);
let mirror = vec2<f32>(p.x + nx * 0.6, hz + 0.05 + clamp(below * 0.9, 0.0, 0.5));
let neb = fbm(mirror * vec2<f32>(3.0, 4.0) + vec2<f32>(t * 0.02, 0.0));
let sky_refl = mix(c1 * 0.5, c5 * 0.6, smoothstep(hz, 0.5, mirror.y)) + mix(c5, c4, neb) * neb * nebula_glow * 0.8 + c3 * stars(mirror * 22.0, t) * 0.5;
let neb_d = noise(p * vec2<f32>(3.0, 4.0) + vec2<f32>(t * 0.02, 0.0));
let stars_v = stars(p * 22.0, t);
let moon_d = sd_circle(p - vec2<f32>(0.42, 0.3), 0.05);
let moon = fill(moon_d) + halo(moon_d, 0.2) * 0.4;
let sky_d = mix(c5 * 0.4, c1 * 0.3, smoothstep(hz, 0.5, p.y)) + mix(c5, c4, neb_d) * neb_d * nebula_glow * 0.8 + c3 * stars_v * 0.8 + c4 * moon;
let deep = mix(c1 * 0.8, c2, clamp(0.5 + h * 0.5, 0.0, 1.0)) * (0.5 + 0.5 * fog);
let water_base = mix(deep, sky_refl, refl_mix * 0.7);
let crest = smoothstep(0.6, 0.95, h * 0.5 + 0.5);
let glint_x = p.x - 0.42 + nx * 0.35;
let glint = (1.0 - smoothstep(0.0, 0.1, abs(glint_x))) * (0.4 + 0.6 * fog) * (0.4 + 0.6 * crest);
let water = water_base + c3 * crest * 0.35 + c4 * glint * 0.9;
let foam = (1.0 - smoothstep(0.0, 0.02, abs(p.y - hz))) * (0.5 + 0.5 * fine) * c3;
let scene = mix(water + foam, sky_d, smoothstep(hz - 0.004, hz + 0.004, p.y));
return mix(bg, tonemap(scene * 1.2), strength);

let hz = -0.03;
let below = max(hz - p.y, 0.015);
let depth = 1.0 / below;
let px = p.x * depth;
let fog = exp(-below * 2.5);
let w1 = noise(vec2<f32>(px * 0.8 + t * 0.15 * wave_speed, depth * 2.0 - t * 0.5 * wave_speed));
let w2 = noise(vec2<f32>(px * 1.7 - t * 0.25 * wave_speed, depth * 4.0 + t * 0.7 * wave_speed));
let ripple = w1 * 0.6 + w2 * 0.4;
let crest = smoothstep(0.55, 0.8, ripple);
let glint_x = p.x - 0.42 + (w2 - 0.5) * 0.12 * (1.0 + depth * 0.2);
let glint = smoothstep(0.1, 0.0, abs(glint_x)) * (0.3 + 0.7 * fog) * (0.5 + 0.5 * crest);
let base = mix(c1 * 0.7, c2, ripple) * (0.5 + 0.5 * fog);
var col = base + c3 * crest * 0.3;
var outline = 0.0;
for (var i = 0; i < 4; i++) {
    let k = f32(i);
    let z = depth * (1.0 + k * 0.45) + sin(px * (0.9 + k * 0.35) - t * wave_speed * (0.5 + k * 0.2) + k * 2.1) * wave_height * (0.4 + k * 0.1);
