let water = mix(col, c1 * 0.4, outline * 0.85) + c4 * glint * 0.7;
let stars_v = stars(p * 22.0, t);
let sky = mix(c5 * 0.45, c1 * 0.3, smoothstep(hz, 0.5, p.y));
let moon_d = sd_circle(p - vec2<f32>(0.42, 0.3), 0.05);
let moon = fill(moon_d) + halo(moon_d, 0.2) * 0.4;
let skyc = sky + c3 * stars_v * 0.8 + c4 * moon;
let foam = smoothstep(0.02, 0.0, abs(p.y - hz)) * (0.4 + 0.6 * ripple) * c3;
let scene = mix(water + foam, skyc, smoothstep(hz - 0.004, hz + 0.004, p.y));
return mix(bg, tonemap(scene), strength);

let hz = -0.03;
let below = max(hz - p.y, 0.015);
let depth = 1.0 / below;
let px = p.x * depth;
let fog = exp(-below * 2.5);
var swell = 0.0;
var ridge = 0.0;
for (var i = 0; i < 4; i++) {
    let k = f32(i);
    let drift = noise(vec2<f32>(px * 0.3 + k * 5.0, depth * 0.4 + t * 0.05 * wave_speed));
    let ph = px * (1.2 + k * 0.7) + drift * 4.0 * wave_height + depth * 0.25 * (1.0 + k * 0.4) - t * wave_speed * (0.9 + k * 0.5);
    let wv = 0.5 + 0.5 * sin(ph);
    swell += wv / (1.0 + k);
    ridge = max(ridge, pow(wv, 6.0 + 4.0 * k));
}
let swell_n = swell / 2.083;
let crest = smoothstep(0.3, 1.0, ridge);
let glint_x = p.x - 0.42 + (swell_n - 0.5) * 0.15 * (1.0 + depth * 0.2);
let glint = (1.0 - smoothstep(0.0, 0.1, abs(glint_x))) * (0.3 + 0.7 * fog) * (0.4 + 0.6 * crest);
let spark_cell = floor(vec2<f32>(px * 10.0, depth * 3.0 - t * wave_speed * 0.5));
let sparkle = step(0.985, hash(spark_cell)) * crest * fog;
let water = mix(c1 * 0.8, c2, swell_n) * (0.5 + 0.5 * fog) + c3 * crest * 0.7 + c4 * glint * 0.9 + c4 * sparkle * 1.2 + c5 * (1.0 - fog) * 0.4;
let stars_v = stars(p * 22.0, t);
let sky = mix(c3 * 0.3, c5 * 0.6, smoothstep(hz, 0.5, p.y));
let moon_d = sd_circle(p - vec2<f32>(0.42, 0.3), 0.05);
let moon = fill(moon_d) + halo(moon_d, 0.2) * 0.4;
let skyc = sky + c3 * stars_v * 0.8 + c4 * moon;
let foam = (1.0 - smoothstep(0.0, 0.02, abs(p.y - hz))) * (0.4 + 0.6 * swell_n) * c3;
let scene = mix(water + foam, skyc, smoothstep(hz - 0.004, hz + 0.004, p.y));
return mix(bg, tonemap(scene * 1.1), strength);

let hz = -0.03;
let below = max(hz - p.y, 0.015);
let depth = 1.0 / below;
let px = p.x * depth;
let fog = exp(-below * 2.5);
var swell = 0.0;
var crest_acc = 0.0;
for (var i = 0; i < 4; i++) {
    let k = f32(i);
    let spd = wave_speed * (0.4 + 0.2 * k);
    let n = noise(vec2<f32>(px * (0.5 + 0.4 * k) - t * 0.2 * spd, depth * (1.2 + 0.7 * k) + t * 0.5 * spd));
    swell += n * (0.5 - 0.08 * k);
    crest_acc += (1.0 - abs(2.0 * n - 1.0)) * (0.3 + 0.1 * k);
}
let crest = smoothstep(0.75 - 0.1 * wave_height, 0.95, crest_acc / 1.8);
let refl_x = p.x - 0.42 + (swell - 0.76) * 0.2 * wave_height;
let road = smoothstep(0.12, 0.0, abs(refl_x)) * (0.4 + 0.6 * fog);
let stripes = smoothstep(0.35, 0.65, 0.5 + 0.5 * sin(depth * 5.0 - t * 2.0 * wave_speed + swell * 3.0));
let glint = road * stripes;
let bp = vec2<f32>(px * 2.0, depth * 3.0 - t * 0.8 * wave_speed);
let bc = floor(bp);
let hb = hash(bc);
let bub = stroke(sd_circle(fract(bp) - 0.5, 0.05 + 0.1 * hb), 0.02) * step(0.92, hb);
let water = mix(c1 * 0.7, c2, clamp(swell, 0.0, 1.0)) * (0.5 + 0.5 * fog) + c3 * crest * (0.25 + 0.5 * fog) + c4 * glint * 0.8 + c3 * bub * fog * 0.6;
let stars_v = stars(p * 22.0, t);
let sky = mix(c5 * 0.45, c1 * 0.3, smoothstep(hz, 0.5, p.y));
let moon_d = sd_circle(p - vec2<f32>(0.42, 0.3), 0.05);
let moon = fill(moon_d) + halo(moon_d, 0.2) * 0.4;
let skyc = sky + c3 * stars_v * 0.8 + c4 * moon;
let foam = smoothstep(0.02, 0.0, abs(p.y - hz)) * (0.4 + 0.6 * crest_acc / 1.8) * c3;
let scene = mix(water + foam, skyc, smoothstep(hz - 0.004, hz + 0.004, p.y));
return mix(bg, tonemap(scene), strength);

let w = p + warp * vec2<f32>(sin(p.y * 13.0 + t * 0.6), sin(p.x * 11.0 - t * 0.5));
let ca = vec2<f32>(0.12 * sin(t * 0.21), 0.08 * cos(t * 0.17));
let cb = -ca;
let sa = sin(length(w - ca) * ring_density * 6.2832 - t * 0.8);
let sb = sin(length(w - cb) * ring_density * 6.2832 + t * 0.6);
let ba = smoothstep(-0.2, 0.2, sa);
let bb = smoothstep(-0.2, 0.2, sb);
let mono = mix(c1, c2, abs(ba - bb));
let accent_ring = stroke(sd_circle(w, accent_radius + 0.015 * sin(t * 0.5)), 0.012);
let color = mix(mono, c3, accent_ring);
return mix(bg, color, strength);
